import { useMemo } from 'react';
import stylingConfig from '../styling.json';

type StylingConfig = typeof stylingConfig;

interface StyleHelpers {
  getColor: (path: string) => string;
  getFont: (name: keyof StylingConfig['fonts']) => string;
  getSpacing: (size: keyof StylingConfig['spacing']) => string;
  getBorderRadius: (size: keyof StylingConfig['borderRadius']) => string;
  getFontSize: (size: keyof StylingConfig['fontSize']) => string;
  getFontWeight: (weight: keyof StylingConfig['fontWeight']) => string;
  getShadow: (size: keyof StylingConfig['shadows']) => string;
  getTransition: (speed: keyof StylingConfig['transitions']) => string;
  createStyle: (styleObj: Record<string, any>) => React.CSSProperties;
}

export const useStyling = (): StylingConfig & StyleHelpers => {
  return useMemo(() => {
    const getNestedValue = (obj: any, path: string): string => {
      return path.split('.').reduce((current, key) => current?.[key], obj) || '';
    };

    const helpers: StyleHelpers = {
      getColor: (path: string) => getNestedValue(stylingConfig.colors, path),
      getFont: (name) => stylingConfig.fonts[name],
      getSpacing: (size) => stylingConfig.spacing[size],
      getBorderRadius: (size) => stylingConfig.borderRadius[size],
      getFontSize: (size) => stylingConfig.fontSize[size],
      getFontWeight: (weight) => stylingConfig.fontWeight[weight],
      getShadow: (size) => stylingConfig.shadows[size],
      getTransition: (speed) => stylingConfig.transitions[speed],
      createStyle: (styleObj) => {
        const processedStyle: Record<string, any> = {};
        
        Object.entries(styleObj).forEach(([key, value]) => {
          if (typeof value === 'string') {
            // Check if it's a reference to a styling config value
            if (value.startsWith('$colors.')) {
              processedStyle[key] = getNestedValue(stylingConfig.colors, value.replace('$colors.', ''));
            } else if (value.startsWith('$fonts.')) {
              processedStyle[key] = stylingConfig.fonts[value.replace('$fonts.', '') as keyof typeof stylingConfig.fonts];
            } else if (value.startsWith('$spacing.')) {
              processedStyle[key] = stylingConfig.spacing[value.replace('$spacing.', '') as keyof typeof stylingConfig.spacing];
            } else if (value.startsWith('$borderRadius.')) {
              processedStyle[key] = stylingConfig.borderRadius[value.replace('$borderRadius.', '') as keyof typeof stylingConfig.borderRadius];
            } else if (value.startsWith('$fontSize.')) {
              processedStyle[key] = stylingConfig.fontSize[value.replace('$fontSize.', '') as keyof typeof stylingConfig.fontSize];
            } else if (value.startsWith('$fontWeight.')) {
              processedStyle[key] = stylingConfig.fontWeight[value.replace('$fontWeight.', '') as keyof typeof stylingConfig.fontWeight];
            } else if (value.startsWith('$shadows.')) {
              processedStyle[key] = stylingConfig.shadows[value.replace('$shadows.', '') as keyof typeof stylingConfig.shadows];
            } else if (value.startsWith('$transitions.')) {
              processedStyle[key] = stylingConfig.transitions[value.replace('$transitions.', '') as keyof typeof stylingConfig.transitions];
            } else {
              processedStyle[key] = value;
            }
          } else {
            processedStyle[key] = value;
          }
        });
        
        return processedStyle as React.CSSProperties;
      }
    };

    return {
      ...stylingConfig,
      ...helpers
    };
  }, []);
};

export default useStyling;