// src/App.tsx - Updated to add React Router for multi-page navigation
import React, { useMemo } from 'react';
import { ConnectionProvider, WalletProvider } from '@solana/wallet-adapter-react';
import { WalletModalProvider } from '@solana/wallet-adapter-react-ui';
import { PhantomWalletAdapter, SolflareWalletAdapter } from '@solana/wallet-adapter-wallets';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import '@solana/wallet-adapter-react-ui/styles.css';
import './App.css';
import MainInterface from './MainInterface';
import PerformanceHistory from './components/PerformanceHistory'; // Import the new component
import Roadmap from './components/Roadmap'; // Import the Roadmap component
import BusinessWhitepaper from './components/BusinessWhitepaper'; // Import Business Whitepaper
import TechnicalWhitepaper from './components/TechnicalWhitepaper'; // Import Technical Whitepaper
import Onboarding from './components/Onboarding'; // Import the Onboarding component
import NewsHub from './components/NewsHub'; // Import the NewsHub component
import ArticleView from './components/ArticleView'; // Import the ArticleView component
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom'; // Add React Router imports

const App = () => {
  const getSyndicaEndpoint = () => {
    const syndicaApiKey = process.env.REACT_APP_SYNDICA_API_KEY;
    if (!syndicaApiKey) {
      console.warn('⚠️ REACT_APP_SYNDICA_API_KEY not set, using public RPC endpoint');
      console.warn('For better performance, consider using a paid RPC provider');
      return 'https://api.mainnet-beta.solana.com';
    }
    return `https://solana-mainnet.api.syndica.io/api-key/${syndicaApiKey}`;
  };

  const endpoint = getSyndicaEndpoint();

  const wallets = useMemo(
    () => [
      new PhantomWalletAdapter(),
      new SolflareWalletAdapter(),
    ],
    []
  );

  return (
    <ConnectionProvider endpoint={endpoint}>
      <WalletProvider wallets={wallets} autoConnect>
        <WalletModalProvider>
          <Router>
            <Routes>
                <Route path="/" element={<MainInterface />} /> // Main page (existing interface)
                <Route path="/docs/performance" element={<PerformanceHistory />} />
                <Route path="/roadmap" element={<Roadmap />} /> // Interactive roadmap page
                <Route path="/business-whitepaper" element={<BusinessWhitepaper />} /> // Business whitepaper page
                <Route path="/technical-whitepaper" element={<TechnicalWhitepaper />} /> // Technical whitepaper page
                <Route path="/onboarding" element={<Onboarding />} /> // Onboarding guide page
                <Route path="/news" element={<NewsHub />} /> // News Hub page
                <Route path="/news/:articleId" element={<ArticleView />} /> // Individual article page

            </Routes>
          </Router>
          <ToastContainer position="bottom-right" autoClose={5000} />
        </WalletModalProvider>
      </WalletProvider>
    </ConnectionProvider>
  );
};

export default App;