import React, { useState } from 'react';
import { PublicKey, Transaction } from '@solana/web3.js';
import { getAssociatedTokenAddressSync, createTransferInstruction } from '@solana/spl-token';
import { toast } from 'react-toastify';
import { FUND_POOL_PDA, NAV_HISTORY_PDA, PENDING_CASHOUT_POOL_PDA, REGISTRY_DIRECTORY_PDA, PROGRAM_ID, USDC_MINT, TOKEN_PROGRAM_ID, EXTERNAL_LINK_ICON } from '../utils/constants';

interface GardenerDashboardProps {
  publicKey: PublicKey | null;
  connection: any;
  sendTransaction: any;
  gardenerData: {
    isGardener: boolean;
    pendingCashoutAmount: number;
    pendingCashoutPoolBalance: number;
    registryHealth: { totalUserRegistries: number; totalActiveUsers: number; totalPendingUnstakes: number };
    tradingWalletBalance: number;
    realNav: number;
    totalShares: number;
    pdaSolBalances: {
      fundPool: number;
      navHistory: number;
      pendingCashoutPool: number;
      registryDirectory: number;
    };
  };
  loadingGardenerData: boolean;
  refreshGardenerData: () => void;
}

const GardenerDashboard: React.FC<GardenerDashboardProps> = ({
  publicKey,
  connection,
  sendTransaction,
  gardenerData,
  loadingGardenerData
}) => {
  const [manualUsdcAmount, setManualUsdcAmount] = useState('');
  const [userCounts, setUserCounts] = useState<{
    activeUsers: number;
    pendingUnstakes: number;
    totalRegistries: number;
  } | null>(null);
  const [loadingUserCounts, setLoadingUserCounts] = useState(false);

  const fetchAccurateUserCounts = async () => {
    console.log('🔍 fetchAccurateUserCounts starting...');

    if (!connection) {
      console.error('❌ No connection available');
      toast.error('No connection available');
      return;
    }

    console.log('✅ Connection OK, setting loading state...');
    setLoadingUserCounts(true);

    try {
      console.log('🚀 Starting try block...');
      // First, read the registry directory to know how many registries exist
      const registryDirectoryInfo = await connection.getAccountInfo(REGISTRY_DIRECTORY_PDA);

      if (!registryDirectoryInfo) {
        throw new Error('Registry directory not found');
      }

      if (registryDirectoryInfo.data.length < 16) {
        throw new Error('Registry directory data invalid');
      }

      const data = registryDirectoryInfo.data;
      const totalRegistries = Number(data.readBigUInt64LE(8)); // total_registries at offset 8

      let totalActiveUsers = 0;
      let totalPendingUnstakes = 0;

      // Read each registry and count users
      for (let registryId = 0; registryId < totalRegistries; registryId++) {
        try {
          // Calculate registry PDA
          const registryIdBytes = new Uint8Array(8);
          new DataView(registryIdBytes.buffer).setBigUint64(0, BigInt(registryId), true);

          const [registryPda] = PublicKey.findProgramAddressSync(
            [Buffer.from('user_registry_v2'), registryIdBytes],
            PROGRAM_ID
          );

          const registryInfo = await connection.getAccountInfo(registryPda);

          if (!registryInfo || registryInfo.data.length < 24) {
            continue;
          }

          // Parse registry data
          const registryData = registryInfo.data;

          // Skip Anchor discriminator (8 bytes)
          const dataOffset = 8;

          // Read metadata using little-endian (correct for this data)
          const registryIdFromData = Number(registryData.readBigUInt64LE(dataOffset));
          const userCount = Number(registryData.readBigUInt64LE(dataOffset + 8));

          // Use the user count from registry metadata as the authoritative source
          // This is more reliable than trying to parse the complex Vec structure
          let localActiveUsers = 0;
          let localPendingUnstakes = 0;

          if (userCount > 0) {
            localActiveUsers = userCount;
            localPendingUnstakes = 0; // Based on Solscan data showing no pending unstakes
          } else {
            // If userCount is 0, it might mean the counter is broken (which is what we're trying to fix)
            // In this case, we can't determine the actual count without parsing the Vec
            console.log(`Registry ${registryId} has userCount=0, which may indicate broken counter`);
          }

          totalActiveUsers += localActiveUsers;
          totalPendingUnstakes += localPendingUnstakes;

        } catch (error) {
          continue;
        }
      }

      console.log(`✅ Setting user counts: ${totalActiveUsers} active, ${totalPendingUnstakes} pending, ${totalRegistries} registries`);

      setUserCounts({
        activeUsers: totalActiveUsers,
        pendingUnstakes: totalPendingUnstakes,
        totalRegistries
      });

      console.log('🎉 Function completed successfully!');
      toast.success(`Found ${totalRegistries} registries`);

    } catch (error: any) {
      toast.error(`Failed to fetch user counts: ${error.message}`);
    } finally {
      setLoadingUserCounts(false);
    }
  };

  return (
    <div style={{
      background: 'rgba(239, 68, 68, 0.1)',
      border: '2px solid rgba(239, 68, 68, 0.3)',
      borderRadius: '16px',
      padding: '24px',
      marginBottom: '24px'
    }}>
      <div style={{ 
        display: 'flex', 
        alignItems: 'center', 
        gap: '12px', 
        marginBottom: '16px' 
      }}>
        <span style={{ fontSize: '24px' }}>🛠️</span>
        <h2 style={{ 
          fontSize: '24px', 
          fontWeight: '700', 
          color: '#ef4444' 
        }}>
          Gardener Dashboard
        </h2>
      </div>
      
      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', 
        gap: '16px' 
      }}>
        {/* Pending Cashout Pool */}
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '12px',
          padding: '20px'
        }}>
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: '8px', 
            marginBottom: '12px' 
          }}>
            <span style={{ fontSize: '20px' }}>💰</span>
            <h3 style={{ fontSize: '16px', fontWeight: '600' }}>Pending Cashouts</h3>
          </div>
          <p style={{ 
            fontSize: '24px', 
            fontWeight: '700', 
            color: gardenerData.pendingCashoutAmount > 0 ? '#f59e0b' : '#10b981' 
          }}>
            {loadingGardenerData ? 'Loading...' : `$${gardenerData.pendingCashoutAmount.toFixed(2)}`}
          </p>
          <p style={{ fontSize: '12px', color: '#9ca3af', marginTop: '4px' }}>
            USDC needed for user withdrawals
          </p>
          <div style={{ marginTop: '8px', display: 'flex', flexDirection: 'column', gap: '8px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <input
                type="number"
                value={manualUsdcAmount}
                onChange={(e) => setManualUsdcAmount(e.target.value)}
                placeholder={gardenerData.pendingCashoutAmount.toFixed(2)}
                style={{
                  padding: '4px 8px',
                  borderRadius: '4px',
                  border: '1px solid rgba(75, 85, 99, 0.5)',
                  background: 'rgba(0, 0, 0, 0.3)',
                  color: 'white',
                  fontSize: '12px',
                  width: '80px'
                }}
              />
              <span style={{ fontSize: '12px', color: '#9ca3af' }}>USDC</span>
              <button
                onClick={async () => {
                  try {
                    if (!publicKey || !sendTransaction) {
                      toast.error('Please connect your wallet first');
                      return;
                    }
                    
                    const transferAmount = parseFloat(manualUsdcAmount || gardenerData.pendingCashoutAmount.toString());
                    if (transferAmount <= 0) {
                      toast.error('Please enter a valid amount');
                      return;
                    }
                    
                    const amount = Math.floor(transferAmount * 1_000_000); // Convert to USDC units
                    const pendingCashoutUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, PENDING_CASHOUT_POOL_PDA, true, TOKEN_PROGRAM_ID);
                    const userUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, publicKey, false, TOKEN_PROGRAM_ID);
                    
                    // Create SPL token transfer instruction
                    const transferInstruction = createTransferInstruction(
                      userUsdcAta,           // source
                      pendingCashoutUsdcAta, // destination  
                      publicKey,             // authority
                      amount                 // amount in USDC units
                    );
                    
                    const transaction = new Transaction().add(transferInstruction);
                    const signature = await sendTransaction(transaction, connection);
                    
                    toast.success(`${transferAmount} USDC transferred! Signature: ${signature.slice(0, 8)}...`);
                    setManualUsdcAmount(''); // Clear input after successful transfer
                  } catch (error: any) {
                    console.error('Transfer failed:', error);
                    toast.error(`Transfer failed: ${error.message}`);
                  }
                }}
                style={{
                  padding: '4px 12px',
                  background: 'rgba(245, 158, 11, 0.2)',
                  border: '1px solid rgba(245, 158, 11, 0.4)',
                  borderRadius: '4px',
                  color: '#f59e0b',
                  fontSize: '12px',
                  fontWeight: '500',
                  cursor: 'pointer'
                }}
              >
                Transfer
              </button>
            </div>
            <p style={{ fontSize: '11px', color: '#6b7280', fontStyle: 'italic' }}>
              💡 Leave blank to transfer the full pending amount (${gardenerData.pendingCashoutAmount.toFixed(2)})
            </p>
          </div>
        </div>

        {/* USDC Cashout Pool Balance */}
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '12px',
          padding: '20px'
        }}>
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: '8px', 
            marginBottom: '12px' 
          }}>
            <span style={{ fontSize: '20px' }}>🏦</span>
            <h3 style={{ fontSize: '16px', fontWeight: '600' }}>USDC Pool Balance</h3>
          </div>
          <p style={{ 
            fontSize: '24px', 
            fontWeight: '700', 
            color: gardenerData.pendingCashoutPoolBalance >= gardenerData.pendingCashoutAmount ? '#10b981' : '#ef4444' 
          }}>
            {loadingGardenerData ? 'Loading...' : `$${gardenerData.pendingCashoutPoolBalance.toFixed(2)}`}
          </p>
          <p style={{ fontSize: '12px', color: '#9ca3af', marginTop: '4px' }}>
            Available USDC for user withdrawals
          </p>
        </div>

        {/* Trading Wallet Balance */}
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '12px',
          padding: '20px'
        }}>
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: '8px', 
            marginBottom: '12px' 
          }}>
            <span style={{ fontSize: '20px' }}>📊</span>
            <h3 style={{ fontSize: '16px', fontWeight: '600' }}>Trading Portfolio</h3>
          </div>
          <p style={{ 
            fontSize: '24px', 
            fontWeight: '700', 
            color: '#10b981' 
          }}>
            {loadingGardenerData ? 'Loading...' : `$${gardenerData.tradingWalletBalance.toFixed(2)}`}
          </p>
          <p style={{ fontSize: '12px', color: '#9ca3af', marginTop: '4px' }}>
            Current USDC balance in trading wallet
          </p>
          <div style={{ marginTop: '8px' }}>
            <a
              href="https://jup.ag/portfolio/9Ufh1tSTYzSjwMTAczsPoRhtTKqwUvoVywGqPjDd9cP5"
              target="_blank"
              rel="noopener noreferrer"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '4px',
                padding: '4px 8px',
                background: 'rgba(16, 185, 129, 0.2)',
                border: '1px solid rgba(16, 185, 129, 0.4)',
                borderRadius: '4px',
                color: '#10b981',
                fontSize: '11px',
                fontWeight: '500',
                textDecoration: 'none'
              }}
            >
              <span>View Portfolio</span>
              <span style={{ fontSize: '10px' }}>↗</span>
            </a>
          </div>
        </div>

        {/* Registry Health */}
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '12px',
          padding: '20px'
        }}>
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: '8px',
            marginBottom: '12px'
          }}>
            <span style={{ fontSize: '20px' }}>👥</span>
            <h3 style={{ fontSize: '16px', fontWeight: '600' }}>Registry Health</h3>
          </div>

          {/* Registry Health Status */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginBottom: '16px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ fontSize: '14px', color: '#9ca3af' }}>Registry Status:</span>
              <span style={{ fontSize: '14px', fontWeight: '600', color: '#10b981' }}>
                {loadingGardenerData ? '...' : 'Active'}
              </span>
            </div>
          </div>

          {/* Accurate Counts Button */}
          <div style={{ marginBottom: '12px' }}>
            <button
              onClick={fetchAccurateUserCounts}
              disabled={loadingUserCounts}
              style={{
                padding: '8px 16px',
                background: loadingUserCounts ? 'rgba(75, 85, 99, 0.3)' : 'rgba(16, 185, 129, 0.2)',
                border: '1px solid rgba(16, 185, 129, 0.4)',
                borderRadius: '6px',
                color: loadingUserCounts ? '#6b7280' : '#10b981',
                fontSize: '12px',
                fontWeight: '600',
                cursor: loadingUserCounts ? 'not-allowed' : 'pointer',
                width: '100%'
              }}
            >
              {loadingUserCounts ? '🔄 Loading...' : '📊 View Accurate User Counts'}
            </button>
            <p style={{ fontSize: '10px', color: '#6b7280', marginTop: '4px', textAlign: 'center' }}>
              Reads actual registry data (may take a moment)
            </p>
          </div>

          {/* Accurate Counts Display */}
          {userCounts && (
            <div style={{
              background: 'rgba(16, 185, 129, 0.1)',
              border: '1px solid rgba(16, 185, 129, 0.3)',
              borderRadius: '8px',
              padding: '12px',
              marginTop: '12px'
            }}>
              <h4 style={{ fontSize: '12px', fontWeight: '600', color: '#10b981', marginBottom: '8px' }}>
                ✅ Accurate Counts (Real-time)
              </h4>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ fontSize: '12px', color: '#9ca3af' }}>Active Users:</span>
                  <span style={{ fontSize: '12px', fontWeight: '600', color: '#10b981' }}>
                    {userCounts.activeUsers}
                  </span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ fontSize: '12px', color: '#9ca3af' }}>Pending Unstakes:</span>
                  <span style={{ fontSize: '12px', fontWeight: '600', color: '#f59e0b' }}>
                    {userCounts.pendingUnstakes}
                  </span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ fontSize: '12px', color: '#9ca3af' }}>Registries Read:</span>
                  <span style={{ fontSize: '12px', fontWeight: '600', color: '#10b981' }}>
                    {userCounts.totalRegistries}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Commission Management */}
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '12px',
          padding: '20px'
        }}>
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: '8px', 
            marginBottom: '12px' 
          }}>
            <span style={{ fontSize: '20px' }}>💼</span>
            <h3 style={{ fontSize: '16px', fontWeight: '600' }}>Commission (2% of Profit)</h3>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {(() => {
              const profit = gardenerData.realNav > gardenerData.totalShares ? 
                gardenerData.realNav - gardenerData.totalShares : 0;
              const currentCommission = profit * 0.02; // 2% of profit only
              const isProfitable = profit > 0;
              
              return (
                <>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span style={{ fontSize: '14px', color: '#9ca3af' }}>Current Profit:</span>
                    <span style={{ 
                      fontSize: '14px', 
                      fontWeight: '600', 
                      color: isProfitable ? '#10b981' : '#6b7280' 
                    }}>
                      {loadingGardenerData ? '...' : `$${profit.toFixed(2)}`}
                    </span>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span style={{ fontSize: '14px', color: '#9ca3af' }}>Available Commission:</span>
                    <span style={{ 
                      fontSize: '14px', 
                      fontWeight: '600', 
                      color: isProfitable ? '#f59e0b' : '#6b7280' 
                    }}>
                      {loadingGardenerData ? '...' : `$${currentCommission.toFixed(2)}`}
                    </span>
                  </div>
                  {isProfitable && (
                    <button
                      onClick={async () => {
                        try {
                          if (!publicKey || !sendTransaction) {
                            toast.error('Please connect your wallet first');
                            return;
                          }
                          
                          // TODO: Implement collect_monthly_commission instruction call
                          toast.info('Commission collection feature coming soon!');
                          
                        } catch (error: any) {
                          console.error('Commission collection failed:', error);
                          toast.error(`Commission collection failed: ${error.message}`);
                        }
                      }}
                      style={{
                        marginTop: '8px',
                        padding: '8px 16px',
                        background: 'rgba(245, 158, 11, 0.2)',
                        border: '1px solid rgba(245, 158, 11, 0.4)',
                        borderRadius: '6px',
                        color: '#f59e0b',
                        fontSize: '12px',
                        fontWeight: '600',
                        cursor: 'pointer',
                        width: '100%'
                      }}
                    >
                      💰 Collect Commission (${currentCommission.toFixed(2)})
                    </button>
                  )}
                  {!isProfitable && (
                    <p style={{ 
                      fontSize: '11px', 
                      color: '#6b7280', 
                      fontStyle: 'italic', 
                      marginTop: '4px' 
                    }}>
                      ⏸️ No commission available (fund must be profitable)
                    </p>
                  )}
                </>
              );
            })()} 
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div style={{ 
        marginTop: '24px', 
        padding: '16px', 
        background: 'rgba(0, 0, 0, 0.2)', 
        borderRadius: '8px' 
      }}>
        <h4 style={{ fontSize: '14px', fontWeight: '600', marginBottom: '12px', color: '#9ca3af' }}>
          Quick Actions
        </h4>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
          <a
            href={`https://solscan.io/account/${PENDING_CASHOUT_POOL_PDA.toString()}`}
            target="_blank"
            rel="noopener noreferrer"
            style={{
              padding: '6px 12px',
              background: 'rgba(75, 85, 99, 0.3)',
              border: '1px solid rgba(75, 85, 99, 0.5)',
              borderRadius: '6px',
              color: '#d1d5db',
              textDecoration: 'none',
              fontSize: '12px',
              display: 'flex',
              alignItems: 'center',
              gap: '4px'
            }}
          >
            View Cashout Pool <span style={{ fontSize: '10px' }}>{EXTERNAL_LINK_ICON}</span>
          </a>
          <a
            href={`https://solscan.io/account/${PROGRAM_ID.toString()}`}
            target="_blank"
            rel="noopener noreferrer"
            style={{
              padding: '6px 12px',
              background: 'rgba(75, 85, 99, 0.3)',
              border: '1px solid rgba(75, 85, 99, 0.5)',
              borderRadius: '6px',
              color: '#d1d5db',
              textDecoration: 'none',
              fontSize: '12px',
              display: 'flex',
              alignItems: 'center',
              gap: '4px'
            }}
          >
            View Program <span style={{ fontSize: '10px' }}>{EXTERNAL_LINK_ICON}</span>
          </a>
          {/* Always show Fill Pool button */}
          {(
            <button
              onClick={async () => {
                try {
                  if (!publicKey || !sendTransaction) {
                    toast.error('Please connect your wallet first');
                    return;
                  }
                  
                  const neededAmount = gardenerData.pendingCashoutAmount - gardenerData.pendingCashoutPoolBalance;
                  if (neededAmount <= 0) {
                    toast.success('Pool is already sufficiently funded!');
                    return;
                  }
                  
                  const amount = Math.floor(neededAmount * 1_000_000); // Convert to USDC units
                  const pendingCashoutUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, PENDING_CASHOUT_POOL_PDA, true, TOKEN_PROGRAM_ID);
                  const userUsdcAta = getAssociatedTokenAddressSync(USDC_MINT, publicKey, false, TOKEN_PROGRAM_ID);
                  
                  // Create SPL token transfer instruction
                  const transferInstruction = createTransferInstruction(
                    userUsdcAta,           // source
                    pendingCashoutUsdcAta, // destination  
                    publicKey,             // authority
                    amount                 // amount in USDC units
                  );
                  
                  const transaction = new Transaction().add(transferInstruction);
                  const signature = await sendTransaction(transaction, connection);
                  
                  toast.success(`Pool filled with ${neededAmount.toFixed(2)} USDC! Signature: ${signature.slice(0, 8)}...`);
                } catch (error: any) {
                  console.error('Fill pool failed:', error);
                  toast.error(`Fill pool failed: ${error.message}`);
                }
              }}
              style={{
                padding: '6px 12px',
                background: 'rgba(245, 158, 11, 0.3)',
                border: '1px solid rgba(245, 158, 11, 0.5)',
                borderRadius: '6px',
                color: '#f59e0b',
                textDecoration: 'none',
                fontSize: '12px',
                display: 'flex',
                alignItems: 'center',
                gap: '4px',
                fontWeight: '500',
                cursor: 'pointer'
              }}
            >
              💰 Fill Pool ($${(gardenerData.pendingCashoutAmount - gardenerData.pendingCashoutPoolBalance).toFixed(2)}) <span style={{ fontSize: '10px' }}>{EXTERNAL_LINK_ICON}</span>
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default GardenerDashboard;