// src/MainInterface.tsx (extracted from original ShrubFundInterface in App.tsx, now acts as the "main" file that references other components/hooks)
import React, { useState } from 'react';
import { useConnection, useWallet } from '@solana/wallet-adapter-react';
import { ToastContainer } from 'react-toastify';
import Header from './components/Header';
import Tabs from './components/Tabs';
import ShrubStakesTab from './components/ShrubStakesTab';
import ShrubSwapsTab from './components/ShrubSwapsTab';
import { ShrubSendInterface } from './ShrubSendComponents';
import useProtocolStats from './hooks/useProtocolStats';
import useUserData from './hooks/useUserData';
import useGardenerData from './hooks/useGardenerData';
import GardenerDashboard from './components/GardenerDashboard';
import { canUnstake } from './utils/shrub-fund-client'; // Imported from new utils file

const MainInterface = () => {
  const { connection } = useConnection();
  const { publicKey, sendTransaction } = useWallet();
  
  const [activeTab, setActiveTab] = useState('shrub-stakes');
  const [activeShrubSendTab, setActiveShrubSendTab] = useState('send');
  
  // Use custom hooks for data fetching (modularized logic)
  const { stats, loadingStats, error: statsError } = useProtocolStats(activeTab, connection);
  const { userInfo, balances, loadingUserData, refreshUserData } = useUserData(publicKey, connection, activeTab, stats.realNav);
  const { gardenerData, loadingGardenerData, refreshGardenerData } = useGardenerData(publicKey, connection, activeTab);

  // Shared handlers can stay here if needed, but most are moved to tab components
  // For example, if a handler needs to refresh shared data, it can call refreshUserData()

  return (
    <div
      className="app"
      style={{
        backgroundImage: `linear-gradient(135deg, rgba(6, 9, 15, 0.8) 0%, rgba(4, 62, 45, 0.8) 50%, rgba(6, 78, 59, 0.8) 100%), url(${require('./background.png')})`,
        backgroundSize: 'cover',
        backgroundPosition: '50% 75%',
        backgroundRepeat: 'no-repeat',
        backgroundAttachment: 'fixed'
      }}
    >
        <Header />
      
      {/* Warning Section */}
      <div className="warning-section">
        <div className="warning-container">
          <div className="warning-box">
            <h3 className="warning-title">Shrub Fund is currently in Beta</h3>
            <p className="warning-text">
              Website and program are currently under development, although program is functional as is, 
              functionality may change without notice. Additionally, investing is inherently risky and 
              Shrub Fund is not responsible for gains or losses.
            </p>
          </div>
        </div>
      </div>
      
      <div className="main-container">
        <Tabs activeTab={activeTab} setActiveTab={setActiveTab} publicKey={publicKey} />

        <div className="content-grid">
          {/* Stats Grid - shown for shrub-stakes tab */}
          {activeTab === 'shrub-stakes' && (
            <div className="stats-grid">
              <div className="stat-card">
                <div className="stat-content">
                  <div>
                    <p className="stat-label">Total Fund Value</p>
                    <p className="stat-value">{loadingStats ? 'Loading...' : `$${stats.totalFundValue.toFixed(2)}`}</p>
                  </div>
                </div>
              </div>

              <div className="stat-card">
                <div className="stat-content">
                  <div>
                    <p className="stat-label">Total Shares Issued</p>
                    <p className="stat-value">{loadingStats ? 'Loading...' : `${stats.totalShares.toFixed(2)}`}</p>
                  </div>
                </div>
              </div>
            </div>
          )}

          <div className="main-card">
            {activeTab === 'shrub-send' && (
              <ShrubSendInterface
                activeSubTab={activeShrubSendTab}
                setActiveSubTab={setActiveShrubSendTab}
              />
            )}

            {activeTab === 'shrub-stakes' && (
              <ShrubStakesTab
                publicKey={publicKey}
                connection={connection}
                sendTransaction={sendTransaction}
                stats={stats}
                userInfo={userInfo}
                balances={balances}
                loadingStats={loadingStats}
                loadingUserData={loadingUserData}
                refreshUserData={refreshUserData}
              />
            )}

            {activeTab === 'shrub-swaps' && (
              <ShrubSwapsTab />
            )}
          </div>
        </div>

        {/* Gardener Dashboard - Visible to gardener when on shrub-stakes tab */}
        {activeTab === 'shrub-stakes' && gardenerData.isGardener && (
          <div style={{ 
            maxWidth: '1200px', 
            margin: '48px auto 0', 
            padding: '0 24px' 
          }}>
            <GardenerDashboard
              publicKey={publicKey}
              connection={connection}
              sendTransaction={sendTransaction}
              gardenerData={gardenerData}
              loadingGardenerData={loadingGardenerData}
              refreshGardenerData={refreshGardenerData}
            />
          </div>
        )}
      </div>
      <ToastContainer position="bottom-right" autoClose={5000} />
    </div>
  );
};

export default MainInterface;