import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import ReactMarkdown from 'react-markdown';
import Header from './Header';

interface ArticleData {
  title: string;
  date: string;
  content: string;
  filename: string;
}

const ArticleView = () => {
  const { articleId } = useParams<{ articleId: string }>();
  const [article, setArticle] = useState<ArticleData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // GitHub repository details
  const GITHUB_OWNER = 'zachdt123';
  const GITHUB_REPO = 'shrubfund.app';
  const NEWS_FOLDER = 'news';

  useEffect(() => {
    if (articleId) {
      fetchArticle(articleId);
    }
  }, [articleId]);

  const fetchArticle = async (filename: string) => {
    try {
      setLoading(true);
      setError(null);

      // Fetch the article content from GitHub
      const response = await fetch(
        `https://api.github.com/repos/${GITHUB_OWNER}/${GITHUB_REPO}/contents/${NEWS_FOLDER}/${filename}`
      );

      if (!response.ok) {
        throw new Error(`Failed to fetch article: ${response.statusText}`);
      }

      const fileData = await response.json();
      const content = await fetch(fileData.download_url).then(res => res.text());

      // Parse the markdown content
      const parsedArticle = parseMarkdownContent(content, filename);
      setArticle(parsedArticle);
    } catch (err) {
      console.error('Error fetching article:', err);
      setError(err instanceof Error ? err.message : 'Failed to load article');
    } finally {
      setLoading(false);
    }
  };

  const parseMarkdownContent = (content: string, filename: string): ArticleData => {
    const lines = content.split('\n');
    let title = filename.replace('.md', '').replace(/-/g, ' ');
    let date = parseDateFromFilename(filename); // Parse date from filename
    let articleContent = content;

    // Check for frontmatter
    if (lines.length > 0 && lines[0].trim() === '---') {
      let frontmatterEnd = -1;
      for (let i = 1; i < lines.length; i++) {
        if (lines[i].trim() === '---') {
          frontmatterEnd = i;
          break;
        }

        // Parse frontmatter (title only, date comes from filename)
        if (lines[i].startsWith('title:') || lines[i].startsWith('Title:')) {
          const titleMatch = lines[i].match(/(?:title|Title):\s*(.+)/);
          if (titleMatch) {
            title = titleMatch[1].trim();
          }
        }
      }

      // Remove frontmatter from content
      if (frontmatterEnd > 0) {
        articleContent = lines.slice(frontmatterEnd + 1).join('\n');
      }
    }

    return {
      title,
      date,
      content: articleContent,
      filename
    };
  };

  // Parse date from filename format: "20250917 12:57 PM-ShrubNews.md"
  const parseDateFromFilename = (filename: string): string => {
    // Remove .md extension
    const nameWithoutExt = filename.replace('.md', '');

    // Match pattern: YYYYMMDD HH:MM AM/PM
    const dateMatch = nameWithoutExt.match(/^(\d{4})(\d{2})(\d{2})\s+(\d{1,2}):(\d{2})\s+(AM|PM)/);

    if (dateMatch) {
      const [, year, month, day, hour, minute, ampm] = dateMatch;

      // Convert to 24-hour format
      let hour24 = parseInt(hour);
      if (ampm === 'PM' && hour24 !== 12) {
        hour24 += 12;
      } else if (ampm === 'AM' && hour24 === 12) {
        hour24 = 0;
      }

      // Create date object
      const date = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), hour24, parseInt(minute));

      // Return in YYYY-MM-DD format for consistency
      return date.toISOString().split('T')[0];
    }

    // Fallback to today's date if parsing fails
    return new Date().toISOString().split('T')[0];
  };

  const formatDate = (dateString: string, filename?: string) => {
    try {
      // If we have the filename, try to extract the full date/time
      if (filename) {
        const nameWithoutExt = filename.replace('.md', '');
        const dateMatch = nameWithoutExt.match(/^(\d{4})(\d{2})(\d{2})\s+(\d{1,2}):(\d{2})\s+(AM|PM)/);

        if (dateMatch) {
          const [, year, month, day, hour, minute, ampm] = dateMatch;

          // Convert to 24-hour format
          let hour24 = parseInt(hour);
          if (ampm === 'PM' && hour24 !== 12) {
            hour24 += 12;
          } else if (ampm === 'AM' && hour24 === 12) {
            hour24 = 0;
          }

          const date = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), hour24, parseInt(minute));

          return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            hour: 'numeric',
            minute: '2-digit',
            hour12: true
          });
        }
      }

      // Fallback to date-only format
      const date = new Date(dateString);
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      });
    } catch {
      return dateString;
    }
  };

  if (loading) {
    return (
      <div
        className="app"
        style={{
          backgroundImage: `linear-gradient(135deg, rgba(6, 9, 15, 0.8) 0%, rgba(4, 62, 45, 0.8) 50%, rgba(6, 78, 59, 0.8) 100%), url(${require('../background.png')})`,
          backgroundSize: 'cover',
          backgroundPosition: '50% 75%',
          backgroundRepeat: 'no-repeat',
          backgroundAttachment: 'fixed'
        }}
      >
        <Header />
        <div className="main-container" style={{ textAlign: 'center', padding: '48px 24px' }}>
          <h1 style={{ color: 'white', marginBottom: '16px' }}>Loading Article...</h1>
          <p style={{ color: '#9ca3af' }}>Please wait while we fetch the article content.</p>
        </div>
      </div>
    );
  }

  if (error || !article) {
    return (
      <div
        className="app"
        style={{
          backgroundImage: `linear-gradient(135deg, rgba(6, 9, 15, 0.8) 0%, rgba(4, 62, 45, 0.8) 50%, rgba(6, 78, 59, 0.8) 100%), url(${require('../background.png')})`,
          backgroundSize: 'cover',
          backgroundPosition: '50% 75%',
          backgroundRepeat: 'no-repeat',
          backgroundAttachment: 'fixed'
        }}
      >
        <Header />
        <div className="main-container" style={{ textAlign: 'center', padding: '48px 24px' }}>
          <h1 style={{ color: 'white', marginBottom: '16px' }}>Article Not Found</h1>
          <p style={{ color: '#ef4444', marginBottom: '24px' }}>
            {error || 'The requested article could not be found.'}
          </p>
          <Link
            to="/news"
            style={{
              color: '#10b981',
              textDecoration: 'none',
              fontSize: '16px',
              fontWeight: 'bold'
            }}
          >
            ← Back to News Hub
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div
      className="app"
      style={{
        backgroundImage: `linear-gradient(135deg, rgba(6, 9, 15, 0.8) 0%, rgba(4, 62, 45, 0.8) 50%, rgba(6, 78, 59, 0.8) 100%), url(${require('../background.png')})`,
        backgroundSize: 'cover',
        backgroundPosition: '50% 75%',
        backgroundRepeat: 'no-repeat',
        backgroundAttachment: 'fixed'
      }}
    >
      <Header />

      

      <div className="main-container">
        <article style={{ maxWidth: '800px', margin: '0 auto' }}>
          {/* Back to News Hub */}
          <div style={{ marginBottom: '24px' }}>
            <Link
              to="/news"
              style={{
                color: '#10b981',
                textDecoration: 'none',
                fontSize: '16px',
                display: 'inline-flex',
                alignItems: 'center',
                gap: '8px'
              }}
            >
              ← Back to News Hub
            </Link>
          </div>

          {/* Article Header */}
          <header style={{ marginBottom: '32px' }}>
            
            <p style={{ color: '#9ca3af', fontSize: '14px' }}>
              Published on {formatDate(article.date, article.filename)}
            </p>
          </header>

          {/* Article Content */}
          <div
            style={{
              background: 'rgba(36, 182, 185, 0.05)',
              backdropFilter: 'blur(2px)',
              border: '1px solid rgba(75, 85, 99, 0.3)',
              borderRadius: '16px',
              padding: '32px',
              lineHeight: 1.7
            }}
          >
            <div style={{ color: '#d1d5db' }}>
              <ReactMarkdown
                components={{
                  h1: ({ children }) => (
                    <h1 style={{ color: 'white', marginBottom: '24px', fontSize: '2rem' }}>
                      {children}
                    </h1>
                  ),
                  h2: ({ children }) => (
                    <h2 style={{ color: 'white', marginTop: '32px', marginBottom: '16px', fontSize: '1.5rem' }}>
                      {children}
                    </h2>
                  ),
                  h3: ({ children }) => (
                    <h3 style={{ color: 'white', marginTop: '24px', marginBottom: '12px', fontSize: '1.25rem' }}>
                      {children}
                    </h3>
                  ),
                  p: ({ children }) => (
                    <p style={{ marginBottom: '16px', color: '#d1d5db' }}>
                      {children}
                    </p>
                  ),
                  ul: ({ children }) => (
                    <ul style={{ marginBottom: '16px', paddingLeft: '24px', color: '#d1d5db' }}>
                      {children}
                    </ul>
                  ),
                  ol: ({ children }) => (
                    <ol style={{ marginBottom: '16px', paddingLeft: '24px', color: '#d1d5db' }}>
                      {children}
                    </ol>
                  ),
                  li: ({ children }) => (
                    <li style={{ marginBottom: '8px', color: '#d1d5db' }}>
                      {children}
                    </li>
                  ),
                  blockquote: ({ children }) => (
                    <blockquote
                      style={{
                        borderLeft: '4px solid #10b981',
                        paddingLeft: '16px',
                        margin: '24px 0',
                        color: '#9ca3af',
                        fontStyle: 'italic'
                      }}
                    >
                      {children}
                    </blockquote>
                  ),
                  code: ({ children }) => (
                    <code
                      style={{
                        background: 'rgba(0, 0, 0, 0.3)',
                        padding: '2px 6px',
                        borderRadius: '4px',
                        fontFamily: 'Monaco, Menlo, Ubuntu Mono, monospace',
                        color: '#60a5fa'
                      }}
                    >
                      {children}
                    </code>
                  ),
                  pre: ({ children }) => (
                    <pre
                      style={{
                        background: 'rgba(0, 0, 0, 0.3)',
                        padding: '16px',
                        borderRadius: '8px',
                        overflow: 'auto',
                        margin: '16px 0',
                        border: '1px solid rgba(75, 85, 99, 0.3)'
                      }}
                    >
                      {children}
                    </pre>
                  ),
                  a: ({ children, href }) => (
                    <a
                      href={href}
                      style={{
                        color: '#10b981',
                        textDecoration: 'none'
                      }}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      {children}
                    </a>
                  )
                }}
              >
                {article.content}
              </ReactMarkdown>
            </div>
          </div>

          {/* Footer */}
          <footer style={{ marginTop: '48px', textAlign: 'center' }}>
            <Link
              to="/news"
              style={{
                color: '#10b981',
                textDecoration: 'none',
                fontSize: '16px',
                fontWeight: 'bold'
              }}
            >
              ← Back to News Hub
            </Link>
          </footer>
        </article>
      </div>
    </div>
  );
};

export default ArticleView;