import React, { useEffect, useRef, useState } from 'react';

declare global {
  interface Window {
    Jupiter: {
      init: (config: any) => void;
    };
  }
}

const ShrubSwapsTab: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const containerElement = containerRef.current;
    let isMounted = true;
    let retryCount = 0;
    const maxRetries = 3;

    const loadJupiterWidget = async () => {
      try {
        // Check if Jupiter is already loaded
        if (typeof window.Jupiter !== 'undefined') {
          if (isMounted) {
            initializeJupiter();
          }
          return;
        }

        // Load Jupiter script with retry logic
        const loadScript = () => new Promise<void>((resolve, reject) => {
          const script = document.createElement('script');
          script.src = 'https://plugin.jup.ag/plugin-v1.js';
          script.async = true;
          script.crossOrigin = 'anonymous';

          script.onload = () => resolve();
          script.onerror = () => {
            if (retryCount < maxRetries) {
              retryCount++;
              console.warn(`Jupiter script load failed, retrying (${retryCount}/${maxRetries})...`);
              setTimeout(() => loadScript().then(resolve).catch(reject), 1000 * retryCount);
            } else {
              reject(new Error('Failed to load Jupiter script after multiple attempts'));
            }
          };

          // Remove any existing Jupiter scripts first
          const existingScript = document.querySelector('script[src*="plugin.jup.ag"]');
          if (existingScript) {
            existingScript.remove();
          }

          document.head.appendChild(script);
        });

        await loadScript();

        // Wait for Jupiter to be available
        let attempts = 0;
        while (typeof window.Jupiter === 'undefined' && attempts < 50) {
          await new Promise(resolve => setTimeout(resolve, 100));
          attempts++;
        }

        if (isMounted && typeof window.Jupiter !== 'undefined') {
          initializeJupiter();
        } else {
          throw new Error('Jupiter failed to initialize after script load');
        }

      } catch (err) {
        console.error('Error loading Jupiter widget:', err);
        if (isMounted) {
          setError(`Failed to load Jupiter swap widget: ${err instanceof Error ? err.message : 'Unknown error'}. Please check your internet connection and try again.`);
          setIsLoading(false);
        }
      }
    };

    const initializeJupiter = () => {
      if (!containerElement) return;

      try {
        window.Jupiter.init({
          displayMode: "integrated",
          integratedTargetId: "jupiter-target-container",
          defaultExplorer: "Solscan",
          formProps: {
            initialInputMint: "So11111111111111111111111111111111111111112", // SOL
            initialOutputMint: "EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v", // USDC
            fixedMint: "",
            referralAccount: "8X1tjuJBthaJRdoRqkn5HsvqnSxtawmKx299VwfJDrjK",
            referralFee: 50,
          },
          branding: {
            name: "Shrub Swap by Jupiter",
            logoUri: "https://raw.githubusercontent.com/zachdt123/SHRB/refs/heads/main/SHRB_img.png",
          },
        });

        if (isMounted) {
          setIsLoading(false);
        }
      } catch (err) {
        console.error('Error initializing Jupiter:', err);
        if (isMounted) {
          setError('Failed to initialize Jupiter widget');
          setIsLoading(false);
        }
      }
    };

    loadJupiterWidget();

    // Cleanup function
    return () => {
      isMounted = false;
      if (containerElement) {
        containerElement.innerHTML = '';
      }
    };
  }, []);

  if (error) {
    return (
      <div>
        <h2 style={{
          color: 'white',
          marginBottom: '24px',
          fontSize: '20px',
          fontWeight: '700',
          textAlign: 'center'
        }}>
          Shrub Swap
        </h2>
        <div style={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          minHeight: '300px'
        }}>
          <div style={{
            background: 'rgba(239, 68, 68, 0.1)',
            border: '1px solid rgba(239, 68, 68, 0.3)',
            borderRadius: '8px',
            padding: '16px',
            color: '#fca5a5',
            maxWidth: '400px',
            width: '100%'
          }}>
            <p style={{ margin: 0, marginBottom: '8px' }}>{error}</p>
            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', justifyContent: 'center' }}>
              <button
                onClick={() => window.location.reload()}
                style={{
                  padding: '8px 16px',
                  background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)',
                  border: 'none',
                  borderRadius: '6px',
                  color: 'white',
                  cursor: 'pointer',
                  fontSize: '14px'
                }}
              >
                Refresh Page
              </button>
              <a
                href="https://jup.ag"
                target="_blank"
                rel="noopener noreferrer"
                style={{
                  padding: '8px 16px',
                  background: 'rgba(59, 130, 246, 0.2)',
                  border: '1px solid rgba(59, 130, 246, 0.3)',
                  borderRadius: '6px',
                  color: '#60a5fa',
                  textDecoration: 'none',
                  fontSize: '14px',
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '4px'
                }}
              >
                Open Jupiter ↗
              </a>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      <h2 style={{
        color: 'white',
        marginBottom: '24px',
        fontSize: '20px',
        fontWeight: '700',
        textAlign: 'center'
      }}>
        Shrub Swap
      </h2>

      {isLoading && (
        <div style={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          height: '300px',
          color: '#9ca3af'
        }}>
          <div>Loading Jupiter Swap Widget...</div>
        </div>
      )}

      <div
        id="jupiter-target-container"
        ref={containerRef}
        style={{
          width: '100%',
          maxWidth: '400px',
          height: '568px',
          margin: '0 auto',
          opacity: isLoading ? 0 : 1,
          transition: 'opacity 0.3s ease'
        }}
      />
    </div>
  );
};

export default ShrubSwapsTab;