import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import Header from './Header';

interface NewsArticle {
  name: string;
  path: string;
  sha: string;
  size: number;
  url: string;
  html_url: string;
  git_url: string;
  download_url: string;
  type: string;
  _links: {
    self: string;
    git: string;
    html: string;
  };
}

interface ParsedArticle {
  filename: string;
  title: string;
  date: string;
  excerpt: string;
  url: string;
  downloadUrl: string;
}

const NewsHub = () => {
  const [articles, setArticles] = useState<ParsedArticle[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // GitHub repository details
  const GITHUB_OWNER = 'zachdt123';
  const GITHUB_REPO = 'shrubfund.app'; // Production repo
  const NEWS_FOLDER = 'news';

  useEffect(() => {
    fetchNewsArticles();
  }, []);

  const fetchNewsArticles = async () => {
    try {
      setLoading(true);
      setError(null);

      let parsedArticles: ParsedArticle[] = [];

      // Try to fetch from GitHub API first
      try {
        const response = await fetch(
          `https://api.github.com/repos/${GITHUB_OWNER}/${GITHUB_REPO}/contents/${NEWS_FOLDER}`
        );

        if (response.ok) {
          const files: NewsArticle[] = await response.json();

          // Filter only .md files
          const mdFiles = files.filter(file => file.name.endsWith('.md'));

          // Parse each .md file to extract metadata
          const githubArticles: ParsedArticle[] = await Promise.all(
            mdFiles.map(async (file) => {
              try {
                const contentResponse = await fetch(file.download_url);
                const content = await contentResponse.text();
                return parseMarkdownFile(file, content);
              } catch (err) {
                console.error(`Error parsing ${file.name}:`, err);
                // Return basic info if parsing fails
                return {
                  filename: file.name,
                  title: file.name.replace('.md', '').replace(/-/g, ' '),
                  date: new Date().toISOString().split('T')[0], // Today's date as fallback
                  excerpt: 'Article content could not be loaded.',
                  url: file.html_url,
                  downloadUrl: file.download_url
                };
              }
            })
          );

          parsedArticles = [...parsedArticles, ...githubArticles];
        }
      } catch (githubErr) {
        console.warn('Could not fetch from GitHub:', githubErr);
      }

      // Sort by date (newest first)
      parsedArticles.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

      setArticles(parsedArticles);
    } catch (err) {
      console.error('Error fetching news articles:', err);
      setError(err instanceof Error ? err.message : 'Failed to load news articles');
    } finally {
      setLoading(false);
    }
  };

  const parseMarkdownFile = (file: NewsArticle, content: string): ParsedArticle => {
    const lines = content.split('\n');
    let title = file.name.replace('.md', '').replace(/-/g, ' ');
    let date = parseDateFromFilename(file.name); // Parse date from filename
    let excerpt = '';

    // Try to extract frontmatter or first heading
    for (let i = 0; i < Math.min(lines.length, 20); i++) {
      const line = lines[i].trim();

      // Check for title in frontmatter (override filename-based title if present)
      if (line.startsWith('title:') || line.startsWith('Title:')) {
        const titleMatch = line.match(/(?:title|Title):\s*(.+)/);
        if (titleMatch) {
          title = titleMatch[1].trim();
        }
      }

      // Check for first heading (fallback for title)
      if (line.startsWith('# ')) {
        title = line.substring(2).trim();
        break;
      }

      // Extract excerpt from first paragraph
      if (line && !line.startsWith('#') && !line.startsWith('---') && excerpt.length < 150) {
        excerpt += line + ' ';
      }
    }

    // Clean up excerpt
    excerpt = excerpt.trim();
    if (excerpt.length > 150) {
      excerpt = excerpt.substring(0, 150) + '...';
    }

    return {
      filename: file.name,
      title,
      date,
      excerpt: excerpt || 'Click to read the full article.',
      url: file.html_url,
      downloadUrl: file.download_url
    };
  };

  // Parse date from filename format: "20250917 12:57 PM-ShrubNews.md"
  const parseDateFromFilename = (filename: string): string => {
    // Remove .md extension
    const nameWithoutExt = filename.replace('.md', '');

    // Match pattern: YYYYMMDD HH:MM AM/PM
    const dateMatch = nameWithoutExt.match(/^(\d{4})(\d{2})(\d{2})\s+(\d{1,2}):(\d{2})\s+(AM|PM)/);

    if (dateMatch) {
      const [, year, month, day, hour, minute, ampm] = dateMatch;

      // Convert to 24-hour format
      let hour24 = parseInt(hour);
      if (ampm === 'PM' && hour24 !== 12) {
        hour24 += 12;
      } else if (ampm === 'AM' && hour24 === 12) {
        hour24 = 0;
      }

      // Create date object
      const date = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), hour24, parseInt(minute));

      // Return in YYYY-MM-DD format for consistency
      return date.toISOString().split('T')[0];
    }

    // Fallback to today's date if parsing fails
    return new Date().toISOString().split('T')[0];
  };

  const formatDate = (dateString: string, filename?: string) => {
    try {
      // If we have the filename, try to extract the full date/time
      if (filename) {
        const nameWithoutExt = filename.replace('.md', '');
        const dateMatch = nameWithoutExt.match(/^(\d{4})(\d{2})(\d{2})\s+(\d{1,2}):(\d{2})\s+(AM|PM)/);

        if (dateMatch) {
          const [, year, month, day, hour, minute, ampm] = dateMatch;

          // Convert to 24-hour format
          let hour24 = parseInt(hour);
          if (ampm === 'PM' && hour24 !== 12) {
            hour24 += 12;
          } else if (ampm === 'AM' && hour24 === 12) {
            hour24 = 0;
          }

          const date = new Date(parseInt(year), parseInt(month) - 1, parseInt(day), hour24, parseInt(minute));

          return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            hour: 'numeric',
            minute: '2-digit',
            hour12: true
          });
        }
      }

      // Fallback to date-only format
      const date = new Date(dateString);
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      });
    } catch {
      return dateString;
    }
  };

  return (
    <div
      className="app"
      style={{
        backgroundImage: `linear-gradient(135deg, rgba(6, 9, 15, 0.8) 0%, rgba(4, 62, 45, 0.8) 50%, rgba(6, 78, 59, 0.8) 100%), url(${require('../background.png')})`,
        backgroundSize: 'cover',
        backgroundPosition: '50% 75%',
        backgroundRepeat: 'no-repeat',
        backgroundAttachment: 'fixed'
      }}
    >
      <Header />

      {/* Warning Section */}
      <div className="warning-section">
        <div className="warning-container">
          <div className="warning-box">
            <h3 className="warning-title">Shrub Fund is currently in Beta</h3>
            <p className="warning-text">
              Website and program are currently under development, although program is functional as is,
              functionality may change without notice. Additionally, investing is inherently risky and
              Shrub Fund is not responsible for gains or losses.
            </p>
          </div>
        </div>
      </div>

      <div className="main-container">
        {loading ? (
          <div style={{ textAlign: 'center', padding: '48px 24px' }}>
            <h1 style={{ color: 'white', marginBottom: '16px' }}>News Hub</h1>
            <p style={{ color: '#9ca3af' }}>Loading news articles...</p>
          </div>
        ) : error ? (
          <div style={{ textAlign: 'center', padding: '48px 24px' }}>
            <h1 style={{ color: 'white', marginBottom: '16px' }}>News Hub</h1>
            <p style={{ color: '#ef4444' }}>Error: {error}</p>
            <button
              onClick={fetchNewsArticles}
              style={{
                marginTop: '16px',
                padding: '8px 16px',
                background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)',
                border: 'none',
                borderRadius: '8px',
                color: 'white',
                cursor: 'pointer'
              }}
            >
              Try Again
            </button>
          </div>
        ) : (
          <>
            <h1 style={{ textAlign: 'center', marginBottom: '32px', color: 'white' }}>News Hub</h1>

            {articles.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '48px 24px' }}>
                <p style={{ color: '#9ca3af', fontSize: '18px' }}>No news articles found. Check back later!</p>
                <p style={{ fontSize: '14px', color: '#6b7280', marginTop: '16px' }}>
                  Articles will appear here automatically when uploaded to the /news/ folder in the GitHub repository.
                </p>
              </div>
            ) : (
              <div style={{
                display: 'grid',
                gap: '24px',
                gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))',
                marginBottom: '48px'
              }}>
                {articles.map((article, index) => (
                  <article
                    key={article.filename}
                    style={{
                      background: 'rgba(36, 182, 185, 0.05)',
                      backdropFilter: 'blur(2px)',
                      border: '1px solid rgba(75, 85, 99, 0.3)',
                      borderRadius: '16px',
                      padding: '24px',
                      transition: 'all 0.3s ease'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.transform = 'translateY(-2px)';
                      e.currentTarget.style.boxShadow = '0 8px 25px rgba(0,0,0,0.3)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.transform = 'translateY(0)';
                      e.currentTarget.style.boxShadow = 'none';
                    }}
                  >
                    <h2 style={{ marginTop: 0, fontSize: '1.25rem', lineHeight: 1.3, color: 'white' }}>
                      <Link
                        to={`/news/${article.filename}`}
                        style={{
                          color: '#10b981',
                          textDecoration: 'none',
                          transition: 'color 0.3s ease'
                        }}
                        onMouseEnter={(e) => {
                          e.currentTarget.style.color = '#6ee7b7';
                        }}
                        onMouseLeave={(e) => {
                          e.currentTarget.style.color = '#10b981';
                        }}
                      >
                        {article.title}
                      </Link>
                    </h2>

                    <p style={{ color: '#9ca3af', fontSize: '14px', marginBottom: '12px' }}>
                      {formatDate(article.date, article.filename)}
                    </p>

                    <p style={{ lineHeight: 1.6, marginBottom: '16px', color: '#d1d5db' }}>
                      {article.excerpt}
                    </p>

                    <Link
                      to={`/news/${article.filename}`}
                      style={{
                        color: '#10b981',
                        textDecoration: 'none',
                        fontWeight: 'bold',
                        fontSize: '14px'
                      }}
                    >
                      Read More →
                    </Link>
                  </article>
                ))}
              </div>
            )}

          </>
        )}
      </div>
    </div>
  );
};

export default NewsHub;