import { PublicKey, Transaction, TransactionInstruction, Connection } from '@solana/web3.js';
import { getAssociatedTokenAddressSync, TOKEN_PROGRAM_ID, ASSOCIATED_TOKEN_PROGRAM_ID } from '@solana/spl-token';
import { WalletContextState } from '@solana/wallet-adapter-react';

// Shrub Send Program ID (update this when deployed)
export const SHRUB_SEND_PROGRAM_ID = new PublicKey("7X6psDPSevanaaCxVPbGMGS4ZmKEH36f7ok6kf4NfSaA");

// Validation constants
const MIN_TRANSFER_AMOUNT = 0.001; // USDC
const MAX_TRANSFER_AMOUNT = 1000000; // USDC

// Helper function to create SHA256 hash
export const createHash = async (input: string): Promise<[number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number]> => {
  const encoder = new TextEncoder();
  const data = encoder.encode(input);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data as BufferSource);
  const hashArray = new Uint8Array(hashBuffer);
  return Array.from(hashArray) as [number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number, number];
};

// Frontend validation functions
export const validateTransferAmount = (amount: string): string | null => {
  const numAmount = parseFloat(amount);
  
  if (isNaN(numAmount)) {
    return 'Amount must be a valid number';
  }
  
  if (numAmount < MIN_TRANSFER_AMOUNT) {
    return `Amount must be at least ${MIN_TRANSFER_AMOUNT} USDC`;
  }
  
  if (numAmount > MAX_TRANSFER_AMOUNT) {
    return `Amount cannot exceed ${MAX_TRANSFER_AMOUNT.toLocaleString()} USDC`;
  }
  
  return null;
};

export const validateCode = (code: string): string | null => {
  if (code.length !== 3) {
    return 'Code must be exactly 3 characters';
  }
  
  if (!/^[a-zA-Z0-9]{3}$/.test(code)) {
    return 'Code must contain only letters and numbers';
  }
  
  return null;
};

export const validateSolanaAddress = (address: string): string | null => {
  // Basic Solana address validation (base58, 32-44 characters)
  if (address.length < 32 || address.length > 44) {
    return 'Invalid address length';
  }
  
  // Check if it's valid base58 characters
  if (!/^[1-9A-HJ-NP-Za-km-z]+$/.test(address)) {
    return 'Address contains invalid characters';
  }
  
  try {
    new PublicKey(address);
    return null;
  } catch {
    return 'Invalid Solana address format';
  }
};

// Helper function to derive sender registry PDA
export const deriveSenderRegistryPda = (senderPubkey: PublicKey): [PublicKey, number] => {
  return PublicKey.findProgramAddressSync(
    [Buffer.from("sender"), senderPubkey.toBuffer()],
    SHRUB_SEND_PROGRAM_ID
  );
};

// Helper function to derive receiver registry PDA
export const deriveReceiverRegistryPda = (receiverPubkey: PublicKey): [PublicKey, number] => {
  return PublicKey.findProgramAddressSync(
    [Buffer.from("receiver"), receiverPubkey.toBuffer()],
    SHRUB_SEND_PROGRAM_ID
  );
};

// Helper function to derive escrow PDA
export const deriveEscrowPda = (senderPubkey: PublicKey, recipientPubkey: PublicKey): [PublicKey, number] => {
  return PublicKey.findProgramAddressSync(
    [Buffer.from("escrow"), senderPubkey.toBuffer(), recipientPubkey.toBuffer()],
    SHRUB_SEND_PROGRAM_ID
  );
};

// Helper function to find the actual bump used for an existing escrow account
export const findActualEscrowBump = async (
  connection: Connection,
  senderPubkey: PublicKey,
  recipientPubkey: PublicKey
): Promise<number | null> => {
  const [expectedPda] = deriveEscrowPda(senderPubkey, recipientPubkey);
  
  // Check if account exists first
  const accountInfo = await connection.getAccountInfo(expectedPda);
  if (!accountInfo) {
    return null; // Account doesn't exist
  }
  
  // Try all possible bumps from 255 down to 0
  for (let bump = 255; bump >= 0; bump--) {
    try {
      const testPda = PublicKey.createProgramAddressSync(
        [Buffer.from("escrow"), senderPubkey.toBuffer(), recipientPubkey.toBuffer(), Buffer.from([bump])],
        SHRUB_SEND_PROGRAM_ID
      );
      
      if (testPda.equals(expectedPda)) {
        console.log(`✅ Found actual bump ${bump} for escrow ${expectedPda.toBase58()}`);
        return bump;
      }
    } catch (error) {
      // This bump doesn't work, continue
    }
  }
  
  console.error('❌ Could not find valid bump for existing escrow account');
  return null;
};

// Interfaces for new dual registry system
export interface SenderSlot {
  recipient: PublicKey;
  amount: number;
  codeHash: number[];
  attempts: number;
  active: boolean;
  currentCommitHash: number[] | null;
}

export interface ReceiverSlot {
  sender: PublicKey;
  amount: number;
  codeHash: number[];
  attempts: number;
  active: boolean;
  currentCommitHash: number[] | null;
}

export interface SenderRegistry {
  slots: SenderSlot[];
}

export interface ReceiverRegistry {
  slots: ReceiverSlot[];
}

// Parse sender registry data
export const parseSenderRegistry = (data: Uint8Array): SenderRegistry | null => {
  try {
    if (data.length < 8) return null;
    
    const slots: SenderSlot[] = [];
    
    // Each registry has 13 fixed slots of exactly 75 bytes each (discovered via reverse engineering)
    const SLOT_SIZE = 75;
    
    for (let i = 0; i < 13; i++) {
      const slotStart = 8 + (i * SLOT_SIZE); // Skip 8-byte discriminator
      
      if (slotStart + SLOT_SIZE > data.length) break;
      
      // Parse each field at correct offsets within the slot
      const recipient = new PublicKey(data.slice(slotStart, slotStart + 32));
      
      // Amount is at offset +32 within slot (confirmed by reverse engineering)
      const amount = Number(new DataView(data.buffer, data.byteOffset + slotStart + 32, 8).getBigUint64(0, true));
      
      // Code hash at offset +40 (32+8) for 32 bytes  
      const codeHash = Array.from(data.slice(slotStart + 40, slotStart + 72));
      
      // Attempts at offset +72
      const attempts = data[slotStart + 72];
      
      // Active flag at offset +73
      const active = data[slotStart + 73] === 1;
      
      // For now, assume no commit hash (last byte may be padding/option)
      const currentCommitHash: number[] | null = null;
      
      slots.push({
        recipient,
        amount,
        codeHash,
        attempts,
        active,
        currentCommitHash
      });
    }
    
    return { slots };
  } catch (error) {
    console.error('Error parsing sender registry:', error);
    return null;
  }
};

// Parse receiver registry data
export const parseReceiverRegistry = (data: Uint8Array): ReceiverRegistry | null => {
  try {
    if (data.length < 8) return null;
    
    const slots: ReceiverSlot[] = [];
    
    // Each registry has 13 fixed slots of exactly 75 bytes each (same structure as sender)
    const SLOT_SIZE = 75;
    
    for (let i = 0; i < 13; i++) {
      const slotStart = 8 + (i * SLOT_SIZE); // Skip 8-byte discriminator
      
      if (slotStart + SLOT_SIZE > data.length) break;
      
      // Parse each field at correct offsets within the slot
      const sender = new PublicKey(data.slice(slotStart, slotStart + 32));
      
      // Amount is at offset +32 within slot
      const amount = Number(new DataView(data.buffer, data.byteOffset + slotStart + 32, 8).getBigUint64(0, true));
      
      // Code hash at offset +40 for 32 bytes
      const codeHash = Array.from(data.slice(slotStart + 40, slotStart + 72));
      
      // Attempts at offset +72
      const attempts = data[slotStart + 72];
      
      // Active flag at offset +73
      const active = data[slotStart + 73] === 1;
      
      // For now, assume no commit hash
      const currentCommitHash: number[] | null = null;
      
      slots.push({
        sender,
        amount,
        codeHash,
        attempts,
        active,
        currentCommitHash
      });
    }
    
    return { slots };
  } catch (error) {
    console.error('Error parsing receiver registry:', error);
    return null;
  }
};

// Get sender registry
export const getSenderRegistry = async (
  connection: Connection,
  senderPubkey: PublicKey
): Promise<SenderRegistry | null> => {
  try {
    const [registryPda] = deriveSenderRegistryPda(senderPubkey);
    const accountInfo = await connection.getAccountInfo(registryPda);
    
    if (!accountInfo) {
      return null; // Registry doesn't exist yet
    }
    
    return parseSenderRegistry(accountInfo.data);
  } catch (error) {
    console.error('Error fetching sender registry:', error);
    return null;
  }
};

// Get receiver registry
export const getReceiverRegistry = async (
  connection: Connection,
  receiverPubkey: PublicKey
): Promise<ReceiverRegistry | null> => {
  try {
    const [registryPda] = deriveReceiverRegistryPda(receiverPubkey);
    const accountInfo = await connection.getAccountInfo(registryPda);
    
    if (!accountInfo) {
      return null; // Registry doesn't exist yet
    }
    
    return parseReceiverRegistry(accountInfo.data);
  } catch (error) {
    console.error('Error fetching receiver registry:', error);
    return null;
  }
};

// Get pending transfers for a recipient
export const getPendingEscrows = async (
  connection: Connection,
  recipientAddress: PublicKey
): Promise<Array<{
  escrowPda: PublicKey;
  sender: PublicKey;
  amount: number;
  mint: PublicKey;
  attemptsLeft: number;
  senderSlotIndex: number;
  receiverSlotIndex: number;
  currentCommitHash: number[] | null;
}>> => {
  try {
    const receiverRegistry = await getReceiverRegistry(connection, recipientAddress);
    if (!receiverRegistry) {
      return [];
    }

    const escrows = [];
    const DEFAULT_USDC_MINT = new PublicKey('EPjFWdd5AufqSSqeM2qN1xzybapC8G4wEGGkZwyTDt1v');

    for (let i = 0; i < receiverRegistry.slots.length; i++) {
      const slot = receiverRegistry.slots[i];
      if (slot.active && slot.attempts < 3) {
        const [escrowPda] = deriveEscrowPda(slot.sender, recipientAddress);
        
        // We need to find the corresponding sender slot index by checking the sender's registry
        const senderRegistry = await getSenderRegistry(connection, slot.sender);
        let senderSlotIndex = -1;
        
        if (senderRegistry) {
          for (let j = 0; j < senderRegistry.slots.length; j++) {
            const senderSlot = senderRegistry.slots[j];
            if (senderSlot.active && 
                senderSlot.recipient.equals(recipientAddress) &&
                senderSlot.amount === slot.amount &&
                JSON.stringify(senderSlot.codeHash) === JSON.stringify(slot.codeHash)) {
              senderSlotIndex = j;
              break;
            }
          }
        }
        
        if (senderSlotIndex >= 0) {
          escrows.push({
            escrowPda,
            sender: slot.sender,
            amount: slot.amount,
            mint: DEFAULT_USDC_MINT,
            attemptsLeft: 3 - slot.attempts,
            senderSlotIndex,
            receiverSlotIndex: i,
            currentCommitHash: slot.currentCommitHash,
          });
        }
      }
    }

    return escrows;
  } catch (error) {
    console.error('Error getting pending escrows:', error);
    return [];
  }
};

