// Send transfer with dual registry system
export const sendTransfer = async (
  connection: Connection,
  wallet: WalletContextState,
  mintAddress: PublicKey,
  recipientAddress: PublicKey,
  amount: number, // in token units
  userCode: string
): Promise<string> => {
  if (!wallet.publicKey || !wallet.sendTransaction) {
    throw new Error('Wallet not connected');
  }

  // Hash the user's code
  const codeHash = await createHash(userCode);

  // Get PDAs
  const [senderRegistryPda] = deriveSenderRegistryPda(wallet.publicKey);
  const [receiverRegistryPda] = deriveReceiverRegistryPda(recipientAddress);
  const [escrowPda] = deriveEscrowPda(wallet.publicKey, recipientAddress);

  // Get token accounts
  const senderTokenAccount = getAssociatedTokenAddressSync(mintAddress, wallet.publicKey);
  const escrowTokenAccount = getAssociatedTokenAddressSync(mintAddress, escrowPda, true);
  
  // Fee collector token account address (directly from smart contract - this IS the ATA)
  const feeCollectorTokenAccount = new PublicKey("8JQiFxvoPEVoSwbTL1EKq9PQmMv1mffqriJ2WpMb7c1d");

  // Build instruction data
  const amountBuffer = Buffer.alloc(8);
  amountBuffer.writeBigUInt64LE(BigInt(amount), 0);
  
  const codeHashBuffer = Buffer.from(codeHash);

  const instructionData = Buffer.concat([
    Buffer.from([153, 182, 142, 63, 227, 31, 140, 239]), // send_transfer discriminator (updated from IDL)
    amountBuffer,
    codeHashBuffer
  ]);

  // Build instruction
  const instruction = new TransactionInstruction({
    keys: [
      { pubkey: wallet.publicKey, isSigner: true, isWritable: true },
      { pubkey: recipientAddress, isSigner: false, isWritable: false },
      { pubkey: mintAddress, isSigner: false, isWritable: false },
      { pubkey: senderRegistryPda, isSigner: false, isWritable: true },
      { pubkey: receiverRegistryPda, isSigner: false, isWritable: true },
      { pubkey: escrowPda, isSigner: false, isWritable: true },
      { pubkey: senderTokenAccount, isSigner: false, isWritable: true },
      { pubkey: feeCollectorTokenAccount, isSigner: false, isWritable: true },
      { pubkey: escrowTokenAccount, isSigner: false, isWritable: true },
      { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
      { pubkey: ASSOCIATED_TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
      { pubkey: new PublicKey('11111111111111111111111111111111'), isSigner: false, isWritable: false }, // System Program
      { pubkey: new PublicKey('SysvarRent111111111111111111111111111111111'), isSigner: false, isWritable: false }, // Rent Sysvar
    ],
    programId: SHRUB_SEND_PROGRAM_ID,
    data: instructionData,
  });

  const transaction = new Transaction().add(instruction);
  
  // Set fee payer and get recent blockhash
  transaction.feePayer = wallet.publicKey;
  const { blockhash } = await connection.getLatestBlockhash();
  transaction.recentBlockhash = blockhash;
  
  const signature = await wallet.sendTransaction(transaction, connection);
  await connection.confirmTransaction(signature, 'confirmed');

  return signature;
};

// Claim transfer with dual registry system (automated commit + reveal)
export const claimTransfer = async (
  connection: Connection,
  wallet: WalletContextState,
  senderSlotIndex: number,
  receiverSlotIndex: number,
  mintAddress: PublicKey,
  inputCode: string,
  senderAddress: PublicKey
): Promise<{ commitSignature: string; revealSignature: string }> => {
  if (!wallet.publicKey || !wallet.sendTransaction) {
    throw new Error('Wallet not connected');
  }

  // Generate a random nonce
  const nonce = Math.floor(Math.random() * 1000000);
  
  // Create commit hash
  const commitData = `${inputCode}${nonce}`;
  const commitHashArray = await createHash(commitData);
  
  // Get PDAs
  const [senderRegistryPda] = deriveSenderRegistryPda(senderAddress);
  const [receiverRegistryPda] = deriveReceiverRegistryPda(wallet.publicKey);
  const [escrowPda] = deriveEscrowPda(senderAddress, wallet.publicKey);
  
  // Find the actual bump used for the escrow account (handles corrupted stored bumps)
  const actualEscrowBump = await findActualEscrowBump(connection, senderAddress, wallet.publicKey);
  if (actualEscrowBump === null) {
    throw new Error('Could not determine escrow account bump');
  }
  

  // Step 1: Commit
  const commitInstruction = new TransactionInstruction({
    keys: [
      { pubkey: wallet.publicKey, isSigner: true, isWritable: true }, // recipient (must be signer)
      { pubkey: senderRegistryPda, isSigner: false, isWritable: true },
      { pubkey: receiverRegistryPda, isSigner: false, isWritable: true },
      { pubkey: senderAddress, isSigner: false, isWritable: false }, // sender (read-only)
    ],
    programId: SHRUB_SEND_PROGRAM_ID,
    data: Buffer.concat([
      Buffer.from([9, 248, 147, 249, 195, 29, 36, 229]), // commit_transfer discriminator (updated from IDL)
      Buffer.from([senderSlotIndex]),
      Buffer.from([receiverSlotIndex]),
      Buffer.from(commitHashArray),
      Buffer.from([actualEscrowBump])
    ]),
  });

  const commitTransaction = new Transaction().add(commitInstruction);
  commitTransaction.feePayer = wallet.publicKey;
  const { blockhash: commitBlockhash } = await connection.getLatestBlockhash();
  commitTransaction.recentBlockhash = commitBlockhash;
  
  const commitSignature = await wallet.sendTransaction(commitTransaction, connection);
  await connection.confirmTransaction(commitSignature, 'confirmed');
  
  // Wait a moment for commit to be confirmed
  await new Promise(resolve => setTimeout(resolve, 1000));
  
  // Step 2: Reveal
  const escrowTokenAccount = getAssociatedTokenAddressSync(mintAddress, escrowPda, true);
  const recipientTokenAccount = getAssociatedTokenAddressSync(mintAddress, wallet.publicKey);
  const senderTokenAccount = getAssociatedTokenAddressSync(mintAddress, senderAddress);


  const codeBuffer = Buffer.from(inputCode, 'utf8');
  
  const revealInstruction = new TransactionInstruction({
    keys: [
      { pubkey: wallet.publicKey, isSigner: true, isWritable: true }, // recipient (must be signer)
      { pubkey: mintAddress, isSigner: false, isWritable: false },
      { pubkey: senderRegistryPda, isSigner: false, isWritable: true },
      { pubkey: receiverRegistryPda, isSigner: false, isWritable: true },
      { pubkey: escrowPda, isSigner: false, isWritable: true },
      { pubkey: escrowTokenAccount, isSigner: false, isWritable: true },
      { pubkey: recipientTokenAccount, isSigner: false, isWritable: true },
      { pubkey: senderTokenAccount, isSigner: false, isWritable: true },
      { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
      { pubkey: ASSOCIATED_TOKEN_PROGRAM_ID, isSigner: false, isWritable: false },
      { pubkey: new PublicKey('11111111111111111111111111111111'), isSigner: false, isWritable: false },
      { pubkey: new PublicKey('SysvarRent111111111111111111111111111111111'), isSigner: false, isWritable: false },
      { pubkey: senderAddress, isSigner: false, isWritable: false }, // sender (read-only, moved to end)
    ],
    programId: SHRUB_SEND_PROGRAM_ID,
    data: Buffer.concat([
      Buffer.from([31, 141, 227, 234, 205, 189, 136, 167]), // reveal_transfer discriminator (updated from IDL)
      Buffer.from([senderSlotIndex]),
      Buffer.from([receiverSlotIndex]),
      Buffer.from([codeBuffer.length & 0xff, (codeBuffer.length >> 8) & 0xff, (codeBuffer.length >> 16) & 0xff, (codeBuffer.length >> 24) & 0xff]),
      codeBuffer,
      Buffer.from([nonce & 0xff, (nonce >> 8) & 0xff, (nonce >> 16) & 0xff, (nonce >> 24) & 0xff, 0, 0, 0, 0]),
      Buffer.from(commitHashArray)
    ]),
  });

  const revealTransaction = new Transaction().add(revealInstruction);
  revealTransaction.feePayer = wallet.publicKey;
  const { blockhash: revealBlockhash } = await connection.getLatestBlockhash();
  revealTransaction.recentBlockhash = revealBlockhash;
  
  // Simulate reveal transaction to catch wrong codes before user signs
  try {
    const simulation = await connection.simulateTransaction(revealTransaction);
    
    if (simulation.value.err) {
      // Check if it's likely a wrong code error
      const logs = simulation.value.logs || [];
      const hasInvalidCodeError = logs.some(log => 
        log.includes('InvalidCode') || 
        log.includes('InvalidReveal')
      );
      const hasAttemptsExhausted = logs.some(log => 
        log.includes('AttemptsExhausted')
      );
      
      if (hasInvalidCodeError) {
        throw new Error('INVALID_CODE'); // Special error type
      } else if (hasAttemptsExhausted) {
        throw new Error('ATTEMPTS_EXHAUSTED'); // Special error type
      } else {
        throw new Error(`SIMULATION_FAILED: ${JSON.stringify(simulation.value.err)}`);
      }
    }
  } catch (simError: any) {
    // Re-throw our special error types
    if (simError.message.includes('INVALID_CODE') || 
        simError.message.includes('ATTEMPTS_EXHAUSTED') ||
        simError.message.includes('SIMULATION_FAILED')) {
      throw simError;
    }
    throw new Error(`SIMULATION_ERROR: ${simError.message}`);
  }
  
  const revealSignature = await wallet.sendTransaction(revealTransaction, connection);
  await connection.confirmTransaction(revealSignature, 'confirmed');
  
  return { commitSignature, revealSignature };
};

// Recall funds - sender can retrieve funds at any time
export const recallFunds = async (
  connection: Connection,
  wallet: WalletContextState,
  senderSlotIndex: number,
  receiverSlotIndex: number,
  mintAddress: PublicKey,
  recipientAddress: PublicKey
): Promise<string> => {
  if (!wallet.publicKey || !wallet.sendTransaction) {
    throw new Error('Wallet not connected');
  }

  // Get PDAs with bumps
  const [senderRegistryPda, senderRegistryBump] = deriveSenderRegistryPda(wallet.publicKey);
  const [receiverRegistryPda, receiverRegistryBump] = deriveReceiverRegistryPda(recipientAddress);
  const [escrowPda, escrowBump] = deriveEscrowPda(wallet.publicKey, recipientAddress);

  console.log('🔍 Recall Funds Debug Info:');
  console.log('Sender:', wallet.publicKey.toBase58());
  console.log('Recipient:', recipientAddress.toBase58());
  console.log('Sender Registry PDA:', senderRegistryPda.toBase58());
  console.log('Receiver Registry PDA:', receiverRegistryPda.toBase58());
  console.log('Escrow PDA:', escrowPda.toBase58());
  console.log('Sender Slot Index:', senderSlotIndex);
  console.log('Receiver Slot Index:', receiverSlotIndex);

  // Find the actual bump used for this escrow account (workaround for corrupted stored bumps)
  console.log('🔍 Finding actual bump for escrow account...');
  const actualBump = await findActualEscrowBump(connection, wallet.publicKey, recipientAddress);
  
  if (actualBump === null) {
    throw new Error('Escrow account not found or could not determine valid bump');
  }
  
  console.log(`✅ Using actual bump ${actualBump} for escrow validation`);

  // Get token accounts
  const escrowTokenAccount = getAssociatedTokenAddressSync(mintAddress, escrowPda, true);
  const senderTokenAccount = getAssociatedTokenAddressSync(mintAddress, wallet.publicKey);

  console.log('Token Accounts:');
  console.log('Escrow Token Account:', escrowTokenAccount.toBase58());
  console.log('Sender Token Account:', senderTokenAccount.toBase58());
  console.log('Mint:', mintAddress.toBase58());

  // Validate token accounts exist
  try {
    const escrowTokenAccountInfo = await connection.getAccountInfo(escrowTokenAccount);
    if (!escrowTokenAccountInfo) {
      throw new Error('Escrow token account not found. No funds to recall.');
    }
    
    const senderTokenAccountInfo = await connection.getAccountInfo(senderTokenAccount);
    if (!senderTokenAccountInfo) {
      throw new Error('Sender token account not found. Please create a USDC account first.');
    }
  } catch (error) {
    console.error('Error validating token accounts:', error);
    throw error;
  }

  // Validate slot data integrity before attempting recall
  try {
    const senderRegistry = await getSenderRegistry(connection, wallet.publicKey);
    const receiverRegistry = await getReceiverRegistry(connection, recipientAddress);
    
    if (!senderRegistry || !receiverRegistry) {
      throw new Error('Registry accounts not found');
    }
    
    const senderSlot = senderRegistry.slots[senderSlotIndex];
    const receiverSlot = receiverRegistry.slots[receiverSlotIndex];
    
    console.log('Slot Validation:');
    console.log('Sender Slot:', senderSlot);
    console.log('Receiver Slot:', receiverSlot);
    
    if (!senderSlot.active || !receiverSlot.active) {
      throw new Error('One or both slots are not active');
    }
    
    if (!senderSlot.recipient.equals(recipientAddress)) {
      throw new Error('Sender slot recipient mismatch');
    }
    
    if (!receiverSlot.sender.equals(wallet.publicKey)) {
      throw new Error('Receiver slot sender mismatch');
    }
    
    if (senderSlot.amount !== receiverSlot.amount) {
      throw new Error('Amount mismatch between slots');
    }
    
    console.log('✅ Slot validation passed');
  } catch (error) {
    console.error('❌ Slot validation failed:', error);
    throw error;
  }

  // Build instruction data with explicit bump
  const instructionData = Buffer.concat([
    Buffer.from([17, 8, 165, 196, 200, 244, 149, 14]), // recall_funds discriminator
    Buffer.from([senderSlotIndex]),
    Buffer.from([receiverSlotIndex]),
    Buffer.from([actualBump])
  ]);

  // Build instruction - match RecallFunds context in lib.rs
  const instruction = new TransactionInstruction({
    keys: [
      { pubkey: wallet.publicKey, isSigner: true, isWritable: true }, // sender
      { pubkey: recipientAddress, isSigner: false, isWritable: false }, // recipient
      { pubkey: mintAddress, isSigner: false, isWritable: false }, // mint
      { pubkey: senderRegistryPda, isSigner: false, isWritable: true }, // sender_registry
      { pubkey: receiverRegistryPda, isSigner: false, isWritable: true }, // receiver_registry
      { pubkey: escrowPda, isSigner: false, isWritable: true }, // escrow
      { pubkey: escrowTokenAccount, isSigner: false, isWritable: true }, // escrow_token_account
      { pubkey: senderTokenAccount, isSigner: false, isWritable: true }, // sender_token_account
      { pubkey: TOKEN_PROGRAM_ID, isSigner: false, isWritable: false }, // token_program
    ],
    programId: SHRUB_SEND_PROGRAM_ID,
    data: instructionData,
  });

  const transaction = new Transaction().add(instruction);
  transaction.feePayer = wallet.publicKey;
  const { blockhash } = await connection.getLatestBlockhash();
  transaction.recentBlockhash = blockhash;
  
  console.log('🚀 Attempting to simulate transaction...');
  
  try {
    // Simulate the transaction first to catch any errors
    const simulation = await connection.simulateTransaction(transaction);
    console.log('Simulation result:', simulation);
    
    if (simulation.value.err) {
      console.error('❌ Transaction simulation failed:', simulation.value.err);
      console.error('Logs:', simulation.value.logs);
      throw new Error(`Transaction simulation failed: ${JSON.stringify(simulation.value.err)}`);
    }
    
    console.log('✅ Simulation successful, sending transaction...');
  } catch (simError) {
    console.error('❌ Simulation error:', simError);
    throw simError;
  }
  
  const signature = await wallet.sendTransaction(transaction, connection);
  await connection.confirmTransaction(signature, 'confirmed');

  return signature;
};


