import React, { useEffect, useState } from 'react';
import Header from '../components/Header';
import { useConnection } from '@solana/wallet-adapter-react';
import { PublicKey } from '@solana/web3.js';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { FUND_POOL_PDA, PROGRAM_ID, DISCRIMINATORS } from '../utils/constants';

interface NavSnapshot {
  timestamp: number;
  date: string;
  optimizedNavPerShare: number;
  realNavPerShare: number;
  totalShares: number;
  realNav: number;
}

interface TransactionData {
  signature: string;
  timestamp: number;
  type: 'nav_update' | 'stake' | 'unstake_initiate' | 'unstake_complete';
  data: any;
}

const PerformanceHistory: React.FC = () => {
  const { connection } = useConnection();
  const [history, setHistory] = useState<NavSnapshot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [debugInfo, setDebugInfo] = useState<string[]>([]);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [loadingStatus, setLoadingStatus] = useState('');

  const addDebugInfo = (message: string) => {
    console.log('[PerformanceHistory]', message);
    setDebugInfo(prev => [...prev, `${new Date().toISOString()}: ${message}`]);
  };

  // Rate limiter to avoid RPC throttling (max 50 requests per second)
  const rateLimiter = {
    requests: [] as number[],
    maxRequests: 45, // Leave some buffer below 50
    windowMs: 1000,

    async waitForSlot() {
      const now = Date.now();
      // Remove requests outside the time window
      this.requests = this.requests.filter(time => now - time < this.windowMs);

      if (this.requests.length >= this.maxRequests) {
        const oldestRequest = Math.min(...this.requests);
        const waitTime = this.windowMs - (now - oldestRequest);
        if (waitTime > 0) {
          addDebugInfo(`Rate limiting: waiting ${waitTime}ms`);
          await new Promise(resolve => setTimeout(resolve, waitTime));
        }
      }

      this.requests.push(now);
    }
  };

  useEffect(() => {
    const fetchHistory = async () => {
      setLoading(true);
      setError(null);
      setDebugInfo([]);
      addDebugInfo('Starting performance history fetch');

      try {
        const fundPoolPubkey = new PublicKey(FUND_POOL_PDA);
        setLoadingStatus('Fetching transaction signatures...');
        setLoadingProgress(10);
        addDebugInfo(`Fetching signatures for PDA: ${FUND_POOL_PDA}`);

        // Fetch more transactions to ensure we capture stake/unstake events
        await rateLimiter.waitForSlot();
        let signatures = await connection.getSignaturesForAddress(fundPoolPubkey, { limit: 500 });
        setLoadingProgress(15);
        addDebugInfo(`Fetched ${signatures.length} initial signatures`);

        // Paginate to get more historical transactions
        let before = signatures.length > 0 ? signatures[signatures.length - 1].signature : null;
        let pageCount = 1;
        while (signatures.length < 1000 && before && pageCount < 5) { // Max 1000 transactions, 5 pages
          await rateLimiter.waitForSlot();
          const moreSignatures = await connection.getSignaturesForAddress(fundPoolPubkey, {
            limit: 200,
            before: before,
          });
          if (moreSignatures.length > 0) {
            signatures = signatures.concat(moreSignatures);
            before = moreSignatures[moreSignatures.length - 1].signature;
            pageCount++;
            addDebugInfo(`Added ${moreSignatures.length} more signatures, total: ${signatures.length}`);
          } else {
            break;
          }
        }
        setLoadingProgress(25);

        const transactions: TransactionData[] = [];

        // Get the CORRECT current total_shares from the fund pool account (same as homepage)
        setLoadingStatus('Getting current fund data...');
        setLoadingProgress(25);
        let currentTotalShares = 0;
        try {
          const fundPoolInfo = await connection.getAccountInfo(FUND_POOL_PDA);
          if (fundPoolInfo && fundPoolInfo.data.length >= 81) {
            const data = fundPoolInfo.data;
            currentTotalShares = Number(data.readBigUInt64LE(8)); // Same offset as useProtocolStats
            addDebugInfo(`Got current total_shares from fund pool: ${currentTotalShares} (raw) = ${currentTotalShares / 1_000_000} shares`);
          }
        } catch (error) {
          addDebugInfo(`Error getting current fund data: ${error}`);
        }

        // Track pending unstakes for historical reconstruction
        const pendingUnstakes: { [userKey: string]: { shares: number; timestamp: number } } = {};

        setLoadingStatus('Processing transactions...');
        setLoadingProgress(30);
        addDebugInfo(`Starting with current total_shares: ${currentTotalShares} (raw) = ${currentTotalShares / 1_000_000} shares`);

        // Process transactions from newest to oldest for backward reconstruction
        const processedSignatures = signatures; // Already newest first

        // Initialize historical shares for backward reconstruction
        let historicalShares = currentTotalShares;

        // Check for specific transactions mentioned by user
        const targetSignatures = [
          'Sbux9K9i9MKMEd2K2VSHHMgDu24NGX7ViHJosawX6m2mj2GLiyMqUBVUYFX3E5VAuPqMkYigpQa9i1Bg2idDFRW',
          '54J6bSFQGRFgL9Vk49XEmnpeLEcUTkzkRnTYPAVGasdJYePPWEeSwH1FmRGx2F2KwXh3KnMW8gNCGKYnANpjT58M',
          '5FEEUfHmWj6XodnZiwjWrov1J3iWngDCBAGALt4DtqdTRsVPqHCDHykbVV3v1rmskwo2H8wk4wd1Hsz9SSTBeqXQ'
        ];

        const foundSignatures = signatures.filter(sig => targetSignatures.some(target => sig.signature.includes(target)));
        if (foundSignatures.length > 0) {
          addDebugInfo(`Found ${foundSignatures.length} target transactions: ${foundSignatures.map(s => s.signature.substring(0, 8)).join(', ')}`);
        } else {
          addDebugInfo('No target transactions found in fetched signatures');
        }

        for (let i = 0; i < processedSignatures.length; i++) {
          const sigInfo = processedSignatures[i];
          const isTargetTx = targetSignatures.some(target => sigInfo.signature.includes(target));
          addDebugInfo(`Processing transaction ${i + 1}/${processedSignatures.length}: ${sigInfo.signature.substring(0, 8)}...${isTargetTx ? ' [TARGET]' : ''} (historical shares: ${historicalShares / 1_000_000})`);

          try {
            await rateLimiter.waitForSlot();
            const tx = await connection.getParsedTransaction(sigInfo.signature, {
              maxSupportedTransactionVersion: 0
            });

            if (!tx || !tx.transaction || !tx.transaction.message) {
              addDebugInfo(`Skipping transaction ${i + 1} - no transaction data`);
              continue;
            }

            // Debug: Log all instructions in this transaction
            addDebugInfo(`Transaction ${i + 1} has ${tx.transaction.message.instructions.length} instructions`);

            // Check if this is a program instruction to our program
            const programInstructions = tx.transaction.message.instructions.filter(
              (ix: any) => {
                const isOurProgram = ix.programId && ix.programId.equals(PROGRAM_ID);
                addDebugInfo(`Instruction programId: ${ix.programId?.toString()}, isOurProgram: ${isOurProgram}`);
                return isOurProgram;
              }
            );

            if (programInstructions.length === 0) {
              addDebugInfo(`Skipping transaction ${i + 1} - no instructions for our program`);
              continue;
            }

            addDebugInfo(`Found ${programInstructions.length} instructions for our program`);

            // Parse instruction data
            for (const ix of programInstructions) {
              // Type guard to check if this is a PartiallyDecodedInstruction with data
              if ('data' in ix && ix.data) {
                addDebugInfo(`Instruction has data: ${ix.data}, length: ${ix.data.length}`);
                const instructionData = Buffer.from(ix.data, 'base64');
                const instructionType = instructionData.slice(0, 8);

                addDebugInfo(`Instruction type bytes: [${Array.from(instructionType).join(', ')}]`);
                addDebugInfo(`Full instruction data: [${Array.from(instructionData).join(', ')}]`);

                // NAV update instruction (update_optimized_nav) - CORRECT discriminator from IDL file
                const navUpdateDiscriminator = Buffer.from(DISCRIMINATORS.update_optimized_nav);
                if (instructionType.equals(navUpdateDiscriminator)) {
                  addDebugInfo(`Found NAV update instruction!`);

                  // Try to extract NAV from log messages first (more reliable)
                  let realNav = 0;
                  if (tx.meta && tx.meta.logMessages) {
                    const navLog = tx.meta.logMessages.find((log: string) => log.includes('NAV updated: Optimized'));
                    if (navLog) {
                      const match = navLog.match(/Real (\d+) USDC/);
                      if (match) {
                        realNav = Number(match[1]);
                        addDebugInfo(`Using NAV from log message: ${realNav} (raw)`);
                      }
                    }
                  }

                  // If log parsing failed, try instruction data (but it's likely garbage)
                  if (realNav === 0 && instructionData.length >= 16) {
                    const newPortfolioValue = instructionData.readBigUInt64LE(8);
                    const instructionNav = Number(newPortfolioValue);

                    // Check if instruction data looks reasonable (not trillions)
                    if (instructionNav < 1_000_000_000_000) { // Less than 1 trillion
                      realNav = instructionNav;
                      addDebugInfo(`Using NAV from instruction data: ${realNav} (raw)`);
                    } else {
                      addDebugInfo(`WARNING: Instruction data NAV ${instructionNav} seems garbage, skipping`);
                    }
                  }

                  if (realNav > 0) {
                    // Convert to proper decimal format (USDC has 6 decimals)
                    const realNavDecimal = realNav / 1_000_000;
                    const totalSharesDecimal = historicalShares / 1_000_000;

                    addDebugInfo(`Converted - NAV: $${realNavDecimal.toFixed(2)}, Historical Shares: ${totalSharesDecimal.toFixed(2)}`);

                    transactions.push({
                      signature: sigInfo.signature,
                      timestamp: sigInfo.blockTime || 0,
                      type: 'nav_update',
                      data: {
                        realNav: realNavDecimal,
                        totalShares: totalSharesDecimal,
                        rawRealNav: realNav,
                        rawTotalShares: historicalShares
                      }
                    });
                  } else {
                    addDebugInfo(`Could not extract valid NAV value from transaction`);
                  }
                }
                // Stake instruction - check both current and old discriminators
                else if (instructionType.equals(Buffer.from(DISCRIMINATORS.stake_usdc)) ||
                         instructionType.equals(Buffer.from([99, 130, 71, 215, 7, 252, 216, 95]))) { // Old discriminator
                  addDebugInfo(`Found stake instruction!`);

                  // Try to extract shares from log messages first (more reliable)
                  let sharesAdded = 0;
                  if (tx.meta && tx.meta.logMessages) {
                    const stakeLog = tx.meta.logMessages.find((log: string) => log.includes('Staked'));
                    if (stakeLog) {
                      const match = stakeLog.match(/Staked (\d+) USDC for (\d+) shares/);
                      if (match) {
                        const usdcAmount = Number(match[1]);
                        sharesAdded = Number(match[2]);
                        addDebugInfo(`Parsed stake from log: ${usdcAmount} USDC -> ${sharesAdded} shares`);
                      }
                    }
                  }

                  // Fallback to instruction data if log parsing failed
                  if (sharesAdded === 0 && instructionData.length >= 16) {
                    const usdcAmount = instructionData.readBigUInt64LE(8);
                    sharesAdded = Number(usdcAmount); // 1 USDC = 1 share initially
                    addDebugInfo(`Parsed stake from instruction data: ${usdcAmount} USDC -> ${sharesAdded} shares`);
                  }

                  if (sharesAdded > 0) {
                    // For backward reconstruction: record current historical shares, then undo the stake
                    transactions.push({
                      signature: sigInfo.signature,
                      timestamp: sigInfo.blockTime || 0,
                      type: 'stake',
                      data: {
                        sharesAdded: sharesAdded,
                        totalShares: historicalShares / 1_000_000
                      }
                    });

                    historicalShares -= sharesAdded;
                    addDebugInfo(`Stake (backward): recorded ${sharesAdded} shares added, historical shares now: ${historicalShares}`);
                  }
                }
                // Unstake initiate instruction
                else if (instructionType.equals(Buffer.from(DISCRIMINATORS.initiate_unstake))) {
                   addDebugInfo(`Found unstake initiate instruction!`);

                   // Parse shares from log messages (similar to NAV parsing)
                   let unstakeShares = 0;
                   if (tx.meta && tx.meta.logMessages) {
                     const unstakeLog = tx.meta.logMessages.find((log: string) => log.includes('Unstake initiated:'));
                     if (unstakeLog) {
                       const match = unstakeLog.match(/Unstake initiated: (\d+) shares/);
                       if (match) {
                         unstakeShares = Number(match[1]);
                         addDebugInfo(`Parsed unstake shares from log: ${unstakeShares}`);
                       }
                     }
                   }

                   // If log parsing failed, try to get shares from instruction data
                   // Note: initiate_unstake doesn't take parameters, so we rely on logs
                   if (unstakeShares === 0) {
                     addDebugInfo(`Could not parse unstake shares from logs - this may cause inaccurate historical share counts`);
                   }

                   // For backward reconstruction: record current historical shares, then undo the unstake
                   if (unstakeShares > 0) {
                     transactions.push({
                       signature: sigInfo.signature,
                       timestamp: sigInfo.blockTime || 0,
                       type: 'unstake_initiate',
                       data: {
                         sharesRemoved: unstakeShares,
                         totalShares: historicalShares / 1_000_000
                       }
                     });

                     historicalShares += unstakeShares;
                     addDebugInfo(`Unstake (backward): recorded ${unstakeShares} shares removed, historical shares now: ${historicalShares}`);
                   }
                }
                // Unstake complete instruction
                else if (instructionType.equals(Buffer.from(DISCRIMINATORS.complete_unstake))) {
                  addDebugInfo(`Found unstake complete instruction!`);
                  // NOTE: Shares are already subtracted in initiate_unstake on-chain
                  // complete_unstake only transfers USDC to user, no share adjustment needed
                  addDebugInfo(`Unstake completion - no share adjustment needed (already handled in initiate)`);
                } else {
                  addDebugInfo(`Unknown instruction type: [${Array.from(instructionType).join(', ')}]`);
                }
              } else {
                addDebugInfo(`Instruction missing data field or data is empty`);
              }
            }
          } catch (txError) {
            addDebugInfo(`Error processing transaction ${i + 1}: ${txError}`);
          }
        }

        addDebugInfo(`Processed ${transactions.length} relevant transactions`);

        // Debug: Log transaction types found
        const transactionTypes = transactions.reduce((acc, tx) => {
          acc[tx.type] = (acc[tx.type] || 0) + 1;
          return acc;
        }, {} as Record<string, number>);
        addDebugInfo(`Transaction types found: ${JSON.stringify(transactionTypes)}`);

        setLoadingStatus('Analyzing NAV updates...');
        setLoadingProgress(70);

        // Create snapshots for both NAV updates and stake/unstake events
        const allEvents = transactions.filter(tx => tx.type === 'nav_update' || tx.type === 'stake' || tx.type === 'unstake_initiate');
        addDebugInfo(`Found ${allEvents.length} relevant events (NAV + stake/unstake)`);
        setLoadingProgress(80);

        const snapshots: NavSnapshot[] = [];
        let lastTimestamp = 0;
        const twelveHours = 12 * 60 * 60 * 1000; // 12 hours in milliseconds

        // Sort events by timestamp
        allEvents.sort((a, b) => a.timestamp - b.timestamp);

        for (const event of allEvents) {
          if (event.timestamp * 1000 - lastTimestamp >= twelveHours || snapshots.length === 0) {
            // For NAV updates, use the NAV data
            if (event.type === 'nav_update') {
              const realNavPerShare = event.data.realNav / event.data.totalShares;

              snapshots.push({
                timestamp: event.timestamp,
                date: new Date(event.timestamp * 1000).toISOString().split('T')[0],
                optimizedNavPerShare: realNavPerShare,
                realNavPerShare: realNavPerShare,
                totalShares: event.data.totalShares,
                realNav: event.data.realNav
              });

              addDebugInfo(`Added NAV snapshot: $${event.data.realNav.toFixed(2)} NAV / ${event.data.totalShares.toFixed(2)} shares = $${realNavPerShare.toFixed(6)} per share`);
            } else {
              // For stake/unstake events, use the historical shares from the transaction data
              // Use the last known NAV per share or a default
              const lastSnapshot = snapshots[snapshots.length - 1];
              const estimatedNavPerShare = lastSnapshot ? lastSnapshot.realNavPerShare : 1.0; // Default to $1.00
              const historicalTotalShares = event.data.totalShares;
              const estimatedTotalNav = historicalTotalShares * estimatedNavPerShare;

              snapshots.push({
                timestamp: event.timestamp,
                date: new Date(event.timestamp * 1000).toISOString().split('T')[0],
                optimizedNavPerShare: estimatedNavPerShare,
                realNavPerShare: estimatedNavPerShare,
                totalShares: historicalTotalShares,
                realNav: estimatedTotalNav
              });

              addDebugInfo(`Added ${event.type} snapshot: ${historicalTotalShares} historical shares at estimated $${estimatedNavPerShare.toFixed(6)} per share`);
            }

            lastTimestamp = event.timestamp * 1000;
          }
        }

        addDebugInfo(`Final historicalShares after backward reconstruction: ${historicalShares} (raw) = ${historicalShares / 1_000_000} shares`);
        addDebugInfo(`Original currentTotalShares: ${currentTotalShares} (raw) = ${currentTotalShares / 1_000_000} shares`);
        addDebugInfo(`Created ${snapshots.length} snapshots for chart`);

        // Debug: Log share values in snapshots
        if (snapshots.length > 0) {
          const shareValues = snapshots.map(s => s.totalShares);
          addDebugInfo(`Historical share values in snapshots: ${shareValues.join(', ')}`);
        }

        setLoadingStatus('Complete!');
        setLoadingProgress(100);
        setHistory(snapshots);

      } catch (err) {
        console.error('Error fetching history:', err);
        addDebugInfo(`Error: ${err}`);
        setError('Failed to load performance history. Please try again.');
      } finally {
        setLoading(false);
      }
    };

    fetchHistory();
  }, [connection]);

  if (loading) return (
    <div style={{
      background: 'rgba(0, 0, 0, 0.3)',
      backdropFilter: 'blur(12px)',
      border: '1px solid rgba(75, 85, 99, 0.3)',
      borderRadius: '16px',
      padding: '24px',
      maxWidth: '1200px',
      margin: '0 auto'
    }}>
      <h2 style={{
        fontSize: '20px',
        fontWeight: '700',
        color: 'white',
        marginBottom: '24px',
        textAlign: 'center'
      }}>
        Loading Performance History
      </h2>

      <div style={{ marginBottom: '24px' }}>
        <div style={{
          width: '100%',
          height: '8px',
          background: 'rgba(55, 65, 81, 0.5)',
          borderRadius: '4px',
          overflow: 'hidden'
        }}>
          <div style={{
            width: `${loadingProgress}%`,
            height: '100%',
            background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)',
            borderRadius: '4px',
            transition: 'width 0.3s ease'
          }} />
        </div>
      </div>

      <div style={{
        textAlign: 'center',
        color: '#9ca3af',
        fontSize: '14px'
      }}>
        {loadingStatus}
      </div>

      {debugInfo.length > 0 && (
        <div style={{
          marginTop: '24px',
          textAlign: 'left',
          maxHeight: '200px',
          overflow: 'auto',
          background: 'rgba(55, 65, 81, 0.3)',
          padding: '16px',
          borderRadius: '8px',
          border: '1px solid rgba(75, 85, 99, 0.3)'
        }}>
          <div style={{
            color: '#d1d5db',
            fontSize: '12px',
            fontWeight: '500',
            marginBottom: '8px'
          }}>
            Debug Info:
          </div>
          <pre style={{
            fontSize: '11px',
            margin: '0',
            color: '#9ca3af',
            lineHeight: '1.4'
          }}>
            {debugInfo.slice(-8).join('\n')}
          </pre>
        </div>
      )}
    </div>
  );

  if (error) return (
    <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
      <div>{error}</div>
      {debugInfo.length > 0 && (
        <div style={{ marginTop: '20px', textAlign: 'left', maxHeight: '300px', overflow: 'auto', background: '#f5f5f5', padding: '10px', borderRadius: '5px' }}>
          <strong>Debug Info:</strong>
          <pre style={{ fontSize: '12px', margin: '10px 0 0 0' }}>
            {debugInfo.join('\n')}
          </pre>
        </div>
      )}
    </div>
  );

  if (history.length === 0) return (
    <div style={{ textAlign: 'center', padding: '20px' }}>
      <div>No history available yet.</div>
      {debugInfo.length > 0 && (
        <div style={{ marginTop: '20px', textAlign: 'left', maxHeight: '300px', overflow: 'auto', background: '#f5f5f5', padding: '10px', borderRadius: '5px' }}>
          <strong>Debug Info:</strong>
          <pre style={{ fontSize: '12px', margin: '10px 0 0 0' }}>
            {debugInfo.join('\n')}
          </pre>
        </div>
      )}
    </div>
  );

  return (
    <div className="app">
      <Header />

      <div style={{
        maxWidth: '1200px',
        margin: '0 auto',
        padding: '32px 24px'
      }}>
      <div style={{
        background: 'rgba(0, 0, 0, 0.3)',
        backdropFilter: 'blur(12px)',
        border: '1px solid rgba(75, 85, 99, 0.3)',
        borderRadius: '16px',
        padding: '24px',
        marginBottom: '24px'
      }}>
        <h2 style={{
          fontSize: '20px',
          fontWeight: '700',
          color: 'white',
          marginBottom: '8px'
        }}>
          Shrub Fund Performance History
        </h2>
        <p style={{
          color: '#9ca3af',
          fontSize: '14px',
          margin: '0'
        }}>
          12-hour intervals based on on-chain NAV updates with historical share counts.
        </p>
      </div>

      {/* Summary Stats */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
        gap: '16px',
        marginBottom: '24px'
      }}>
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          backdropFilter: 'blur(12px)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '12px',
          padding: '16px',
          textAlign: 'center'
        }}>
          <div style={{
            color: '#9ca3af',
            fontSize: '12px',
            marginBottom: '4px'
          }}>
            Total Data Points
          </div>
          <div style={{
            color: 'white',
            fontSize: '18px',
            fontWeight: '700'
          }}>
            {history.length}
          </div>
        </div>
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          backdropFilter: 'blur(12px)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '12px',
          padding: '16px',
          textAlign: 'center'
        }}>
          <div style={{
            color: '#9ca3af',
            fontSize: '12px',
            marginBottom: '4px'
          }}>
            Current Value Per Share
          </div>
          <div style={{
            color: '#10b981',
            fontSize: '18px',
            fontWeight: '700'
          }}>
            ${history.length > 0 ? history[history.length - 1].realNavPerShare.toFixed(6) : 'N/A'}
          </div>
        </div>
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          backdropFilter: 'blur(12px)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '12px',
          padding: '16px',
          textAlign: 'center'
        }}>
          <div style={{
            color: '#9ca3af',
            fontSize: '12px',
            marginBottom: '4px'
          }}>
            Total Shares
          </div>
          <div style={{
            color: 'white',
            fontSize: '18px',
            fontWeight: '700'
          }}>
            {history.length > 0 ? history[history.length - 1].totalShares.toFixed(2) : 'N/A'}
          </div>
        </div>
      </div>

      <div style={{
        background: 'rgba(0, 0, 0, 0.3)',
        backdropFilter: 'blur(12px)',
        border: '1px solid rgba(75, 85, 99, 0.3)',
        borderRadius: '16px',
        padding: '24px',
        marginBottom: '24px'
      }}>
        <h3 style={{
          fontSize: '18px',
          fontWeight: '700',
          color: 'white',
          marginBottom: '16px'
        }}>
          Performance Chart
        </h3>
        <ResponsiveContainer width="100%" height={400}>
          <LineChart data={history}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(75, 85, 99, 0.3)" />
            <XAxis
              dataKey="date"
              stroke="#9ca3af"
              fontSize={12}
            />
            <YAxis
              tickFormatter={(value) => `$${value.toFixed(4)}`}
              stroke="#9ca3af"
              fontSize={12}
            />
            <Tooltip
              formatter={(value: number, name: string) => [`$${value.toFixed(6)}`, name]}
              labelFormatter={(label) => `Date: ${label}`}
              contentStyle={{
                background: 'rgba(0, 0, 0, 0.8)',
                border: '1px solid rgba(75, 85, 99, 0.3)',
                borderRadius: '8px',
                color: 'white'
              }}
            />
            <Legend />
            <Line
              type="monotone"
              dataKey="realNavPerShare"
              stroke="#10b981"
              name="Value Per Share"
              strokeWidth={3}
              dot={{ fill: '#10b981', strokeWidth: 2, r: 4 }}
              activeDot={{ r: 6, stroke: '#10b981', strokeWidth: 2 }}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

      <div style={{
        background: 'rgba(0, 0, 0, 0.3)',
        backdropFilter: 'blur(12px)',
        border: '1px solid rgba(75, 85, 99, 0.3)',
        borderRadius: '16px',
        padding: '24px',
        marginBottom: '24px'
      }}>
        <h3 style={{
          fontSize: '18px',
          fontWeight: '700',
          color: 'white',
          marginBottom: '16px'
        }}>
          Historical Data
        </h3>
        <div style={{ overflowX: 'auto' }}>
          <table style={{
            width: '100%',
            borderCollapse: 'collapse',
            fontSize: '14px'
          }}>
            <thead>
              <tr style={{
                borderBottom: '1px solid rgba(75, 85, 99, 0.3)'
              }}>
                <th style={{
                  padding: '12px 16px',
                  textAlign: 'left',
                  color: '#9ca3af',
                  fontWeight: '500'
                }}>Date</th>
                <th style={{
                  padding: '12px 16px',
                  textAlign: 'right',
                  color: '#9ca3af',
                  fontWeight: '500'
                }}>Value Per Share</th>
                <th style={{
                  padding: '12px 16px',
                  textAlign: 'right',
                  color: '#9ca3af',
                  fontWeight: '500'
                }}>Total Fund Value</th>
                <th style={{
                  padding: '12px 16px',
                  textAlign: 'right',
                  color: '#9ca3af',
                  fontWeight: '500'
                }}>Total Shares</th>
              </tr>
            </thead>
            <tbody>
              {history.map((snap) => (
                <tr key={snap.date} style={{
                  borderBottom: '1px solid rgba(75, 85, 99, 0.2)'
                }}>
                  <td style={{
                    padding: '12px 16px',
                    color: 'white'
                  }}>{snap.date}</td>
                  <td style={{
                    padding: '12px 16px',
                    textAlign: 'right',
                    color: '#10b981',
                    fontWeight: '500'
                  }}>${snap.realNavPerShare.toFixed(6)}</td>
                  <td style={{
                    padding: '12px 16px',
                    textAlign: 'right',
                    color: 'white'
                  }}>${snap.realNav.toFixed(2)}</td>
                  <td style={{
                    padding: '12px 16px',
                    textAlign: 'right',
                    color: 'white'
                  }}>{snap.totalShares.toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Debug Info */}
      {debugInfo.length > 0 && (
        <div style={{
          background: 'rgba(0, 0, 0, 0.3)',
          backdropFilter: 'blur(12px)',
          border: '1px solid rgba(75, 85, 99, 0.3)',
          borderRadius: '16px',
          padding: '24px'
        }}>
          <h3 style={{
            fontSize: '18px',
            fontWeight: '700',
            color: 'white',
            marginBottom: '16px'
          }}>
            Debug Information
          </h3>
          <div style={{
            maxHeight: '300px',
            overflow: 'auto',
            background: 'rgba(55, 65, 81, 0.3)',
            padding: '16px',
            borderRadius: '8px',
            border: '1px solid rgba(75, 85, 99, 0.3)'
          }}>
            <pre style={{
              fontSize: '11px',
              margin: '0',
              color: '#9ca3af',
              lineHeight: '1.4',
              fontFamily: 'Monaco, Menlo, Ubuntu Mono, monospace'
            }}>
              {debugInfo.join('\n')}
            </pre>
          </div>
        </div>
      )}
      </div>
    </div>
  );
};

export default PerformanceHistory;
